import React, { useMemo } from 'react';
import { Partnership, LegalInstrument, Task, View, User } from '../types';
import { ArrowRightIcon, BellIcon, CheckCircleIcon, ClockIcon, CollectionIcon, DocumentReportIcon, ExclamationIcon, XIcon } from './Icons';

interface DashboardProps {
    partnerships: Partnership[];
    legalInstruments: LegalInstrument[];
    tasks: Task[];
    setActiveView: (view: View) => void;
    currentUser: User;
    readHistoryIds: string[];
    onMarkHistoryRead: (id: string) => void;
    onTaskClick: (taskId: string) => void;
}

const StatCard: React.FC<{ title: string; value: string | number; icon: React.ReactNode; color: string; onClick?: () => void }> = ({ title, value, icon, color, onClick }) => (
    <div className={`p-4 bg-white rounded-lg shadow-md flex items-center space-x-4 ${onClick ? 'cursor-pointer hover:bg-gray-50' : ''}`} onClick={onClick}>
        <div className={`p-3 rounded-full ${color}`}>
            {icon}
        </div>
        <div>
            <p className="text-sm font-medium text-gray-500">{title}</p>
            <p className="text-2xl font-semibold text-gray-800">{value}</p>
        </div>
    </div>
);

const Dashboard: React.FC<DashboardProps> = ({ partnerships, legalInstruments, tasks, setActiveView, currentUser, readHistoryIds, onMarkHistoryRead, onTaskClick }) => {
    const isConsultant = currentUser.role === 'Consulta';

    const visiblePartnerships = useMemo(() => {
        return partnerships.filter(p => {
            if (!p.confidential) return true;
            return currentUser.role === 'Administrador' ||
                   [p.ctvCoordinator.id, p.ctvResearcher.id, p.ctvBusinessPartner.id].includes(currentUser.id);
        });
    }, [partnerships, currentUser]);

    // Filter instruments based on visible partnerships
    const visibleInstruments = useMemo(() => {
        const visiblePartnershipIds = visiblePartnerships.map(p => p.id);
        return legalInstruments.filter(i => 
             i.linkedPartnershipIds.some(pid => visiblePartnershipIds.includes(pid))
        );
    }, [legalInstruments, visiblePartnerships]);

    const expiringSoonInstruments = visibleInstruments.filter(inst => {
        const diff = new Date(inst.expirationDate).getTime() - new Date().getTime();
        const days = diff / (1000 * 3600 * 24);
        return days > 0 && days <= 60;
    });

    // Filter tasks: Pending AND assigned to current user
    const pendingTasks = useMemo(() => {
        return tasks
            .filter(task => {
                // Must be assigned to me
                const assignedToMe = task.assignedTo.some(u => u.id === currentUser.id);
                // Must be pending
                return !task.completed && assignedToMe;
            })
            .sort((a, b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime());
    }, [tasks, currentUser.id]);

    const partnershipsExecuting = visiblePartnerships.filter(p => p.status === 'Em execução').length;

    // Filter History:
    // 1. User is involved (Coordinator, Researcher, Business Partner)
    // 2. Not read
    const recentHistory = useMemo(() => {
        const relevantPartnerships = visiblePartnerships.filter(p => 
            p.ctvCoordinator.id === currentUser.id || 
            p.ctvResearcher.id === currentUser.id || 
            p.ctvBusinessPartner.id === currentUser.id
        );

        return relevantPartnerships
            .flatMap(p => p.history.map(entry => ({
                ...entry,
                partnershipReference: p.reference,
            })))
            .filter(entry => !readHistoryIds.includes(entry.id))
            .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
            .slice(0, 5); // Just top 5 unread
    }, [visiblePartnerships, currentUser.id, readHistoryIds]);

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-semibold text-gray-700">Dashboard</h2>

            <div className="grid gap-6 mb-8 md:grid-cols-2 xl:grid-cols-4">
                <StatCard title="Total de Parcerias" value={visiblePartnerships.length} icon={<CollectionIcon className="w-6 h-6 text-white"/>} color="bg-teal-600" onClick={() => setActiveView(View.Partnerships)} />
                <StatCard title="Parcerias em Execução" value={partnershipsExecuting} icon={<ClockIcon className="w-6 h-6 text-teal-900"/>} color="bg-lime-400" />
                <StatCard title="Instrumentos a Vencer" value={expiringSoonInstruments.length} icon={<ExclamationIcon className="w-6 h-6 text-white"/>} color="bg-amber-500" onClick={() => setActiveView(View.LegalInstruments)} />
                <StatCard title="Minhas Tarefas Pendentes" value={pendingTasks.length} icon={<BellIcon className="w-6 h-6 text-white"/>} color="bg-red-500" onClick={() => setActiveView(View.Tasks)} />
            </div>

            <div className="grid gap-6 md:grid-cols-2">
                {/* Recent Activity */}
                <div className="bg-white p-6 rounded-lg shadow-md">
                    <h3 className="text-lg font-semibold mb-4 text-gray-700">Histórico Recente (Relevante para você)</h3>
                    <div className="space-y-4 max-h-80 overflow-y-auto">
                        {recentHistory.map((entry, index) => (
                           <div key={entry.id || index} className="flex items-start space-x-3 group relative pr-8">
                                <div className="bg-teal-100 p-2 rounded-full mt-1">
                                    <CheckCircleIcon className="w-5 h-5 text-teal-600"/>
                                </div>
                                <div className="flex-1">
                                    <p className="text-sm text-gray-600">
                                        <span className="font-semibold text-gray-800">{entry.partnershipReference}:</span> {entry.description}
                                    </p>
                                    <p className="text-xs text-gray-400">{new Date(entry.date).toLocaleString()} por {entry.user}</p>
                                </div>
                                <button 
                                    onClick={() => onMarkHistoryRead(entry.id)}
                                    className="absolute right-0 top-1 text-gray-300 hover:text-teal-600 opacity-0 group-hover:opacity-100 transition-opacity"
                                    title="Marcar como lido"
                                >
                                    <CheckCircleIcon className="w-5 h-5"/>
                                </button>
                           </div>
                        ))}
                        {recentHistory.length === 0 && (
                            <p className="text-sm text-gray-500">Nenhum histórico novo não lido.</p>
                        )}
                    </div>
                </div>

                {/* Overdue Tasks */}
                <div className="bg-white p-6 rounded-lg shadow-md">
                    <h3 className="text-lg font-semibold mb-4 text-gray-700 flex justify-between items-center">
                        <span>Minhas Tarefas Pendentes (Ordem de Vencimento)</span>
                        <button onClick={() => setActiveView(View.Tasks)} className="text-sm text-teal-600 hover:underline flex items-center">Ver todas <ArrowRightIcon className="w-4 h-4 ml-1"/></button>
                    </h3>
                    <div className="space-y-3 max-h-80 overflow-y-auto">
                        {pendingTasks.slice(0, 5).map(task => {
                            const partnership = visiblePartnerships.find(p => p.id === task.partnershipId);
                            const isOverdue = new Date(task.dueDate) < new Date();
                            return (
                                <div 
                                    key={task.id} 
                                    className="p-3 bg-gray-50 rounded-md border border-gray-200 cursor-pointer hover:bg-gray-100 transition-colors"
                                    onClick={() => onTaskClick(task.id)} // Navigates to specific task
                                    title="Clique para abrir esta tarefa"
                                >
                                    <p className="font-semibold text-sm text-gray-800">{task.title}</p>
                                    <p className="text-xs text-gray-500">Parceria: {partnership?.reference}</p>
                                    <p className={`text-xs ${isOverdue ? 'text-red-500 font-bold' : 'text-gray-500'}`}>
                                        Vencimento: {new Date(task.dueDate).toLocaleDateString()}</p>
                                </div>
                            );
                        })}
                         {pendingTasks.length === 0 && <p className="text-sm text-gray-500">Nenhuma tarefa pendente para você.</p>}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Dashboard;

import React, { useState, useEffect, useRef } from 'react';
import { Task, Partnership, User, PartnershipStatus } from '../types';
import Modal from './Modal';
import { SearchIcon } from './Icons';

interface NewTaskModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (task: Omit<Task, 'id' | 'completed' | 'createdBy' | 'creationDate'>) => void;
    partnerships: Partnership[];
    users: User[];
    taskToEdit?: Task | null;
    preSelectedPartnership?: Partnership | null;
}

const initialState = {
    partnershipId: '',
    title: '',
    description: '',
    assignedTo: [],
    dueDate: '',
};


const NewTaskModal: React.FC<NewTaskModalProps> = ({ isOpen, onClose, onSubmit, partnerships, users, taskToEdit, preSelectedPartnership }) => {
    const [formState, setFormState] = useState<Omit<Task, 'id' | 'completed' | 'createdBy' | 'creationDate' | 'assignedTo'> & { assignedTo: string[] } >({
        ...initialState,
        assignedTo: [],
    });

    // Searchable dropdown state
    const [searchTerm, setSearchTerm] = useState('');
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    const isEditing = !!taskToEdit;

    // When editing, allow searching even if partnership is technically finished (to preserve data), otherwise filter.
    const availablePartnerships = isEditing 
        ? partnerships 
        : partnerships.filter(p => p.status !== PartnershipStatus.Finished && p.status !== PartnershipStatus.Rejected);

    const filteredPartnerships = availablePartnerships.filter(p => 
        p.reference.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.title.toLowerCase().includes(searchTerm.toLowerCase())
    );

    useEffect(() => {
        if (isOpen) {
            if (taskToEdit) {
                setFormState({
                    partnershipId: taskToEdit.partnershipId,
                    title: taskToEdit.title,
                    description: taskToEdit.description,
                    assignedTo: taskToEdit.assignedTo.map(u => u.id),
                    dueDate: taskToEdit.dueDate,
                });
                const p = partnerships.find(p => p.id === taskToEdit.partnershipId);
                if (p) setSearchTerm(`${p.reference} - ${p.title}`);
            } else if (preSelectedPartnership) {
                setFormState({
                     ...initialState,
                     partnershipId: preSelectedPartnership.id,
                     assignedTo: [],
                });
                setSearchTerm(`${preSelectedPartnership.reference} - ${preSelectedPartnership.title}`);
            } else {
                setFormState({ ...initialState, assignedTo: [] });
                setSearchTerm('');
            }
            setIsDropdownOpen(false);
        }
    }, [isOpen, taskToEdit, partnerships, preSelectedPartnership]);

    // Close dropdown when clicking outside
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormState(prev => ({ ...prev, [name]: value }));
    };

    const handleUserChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const selectedIds = Array.from(e.target.selectedOptions, (option: HTMLOptionElement) => option.value);
        setFormState(prev => ({ ...prev, assignedTo: selectedIds }));
    };

    const handlePartnershipSelect = (partnership: Partnership) => {
        setFormState(prev => ({ ...prev, partnershipId: partnership.id }));
        setSearchTerm(`${partnership.reference} - ${partnership.title}`);
        setIsDropdownOpen(false);
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!formState.partnershipId || !formState.title || !formState.dueDate) {
            alert('Por favor, preencha todos os campos obrigatórios e selecione uma parceria válida.');
            return;
        }

        const assignedUsers = users.filter(user => formState.assignedTo.includes(user.id));

        onSubmit({
            ...formState,
            assignedTo: assignedUsers,
        });
    };

    const isPartnershipLocked = !!preSelectedPartnership && !isEditing;

    return (
        <Modal 
            isOpen={isOpen} 
            onClose={onClose} 
            title={isEditing ? 'Editar Tarefa' : 'Criar Nova Tarefa'}
            footer={
                <>
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300">
                        Cancelar
                    </button>
                    <button 
                        type="submit" 
                        form="task-form"
                        className="px-4 py-2 bg-teal-600 text-white rounded-md hover:bg-teal-700 disabled:bg-gray-400"
                        disabled={availablePartnerships.length === 0}
                    >
                        {isEditing ? 'Salvar Alterações' : 'Salvar Tarefa'}
                    </button>
                </>
            }
        >
            <form id="task-form" onSubmit={handleSubmit}>
                <div className="grid grid-cols-1 gap-4">
                    {availablePartnerships.length > 0 ? (
                        <div className="relative" ref={dropdownRef}>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Parceria Vinculada</label>
                            <div className="relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                    <SearchIcon className="h-4 w-4 text-gray-400" />
                                </div>
                                <input
                                    type="text"
                                    placeholder="Buscar parceria por referência ou título..."
                                    value={searchTerm}
                                    onChange={(e) => {
                                        setSearchTerm(e.target.value);
                                        setIsDropdownOpen(true);
                                        setFormState(prev => ({ ...prev, partnershipId: '' })); // Clear selection on type
                                    }}
                                    onFocus={() => !isPartnershipLocked && setIsDropdownOpen(true)}
                                    disabled={isPartnershipLocked}
                                    className={`block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm ${isPartnershipLocked ? 'bg-gray-100 cursor-not-allowed' : ''}`}
                                />
                            </div>

                            {isDropdownOpen && !isPartnershipLocked && (
                                <ul className="absolute z-10 mt-1 w-full bg-white shadow-lg max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
                                    {filteredPartnerships.length === 0 ? (
                                        <li className="text-gray-500 cursor-default select-none relative py-2 px-3 pl-9">
                                            Nenhuma parceria encontrada.
                                        </li>
                                    ) : (
                                        filteredPartnerships.map((p) => (
                                            <li
                                                key={p.id}
                                                className="cursor-pointer select-none relative py-2 pl-3 pr-9 hover:bg-teal-50 text-gray-900"
                                                onClick={() => handlePartnershipSelect(p)}
                                            >
                                                <div className="flex flex-col">
                                                    <span className="font-medium">{p.reference}</span>
                                                    <span className="text-xs text-gray-500">{p.title}</span>
                                                </div>
                                            </li>
                                        ))
                                    )}
                                </ul>
                            )}
                            {formState.partnershipId === '' && searchTerm !== '' && !isDropdownOpen && (
                                <p className="text-xs text-red-500 mt-1">Selecione uma parceria da lista.</p>
                            )}
                        </div>
                    ) : (
                        <div className="p-4 text-center bg-yellow-50 border border-yellow-200 rounded-md">
                            <p className="text-sm text-yellow-700">Não há parcerias ativas disponíveis para vincular uma nova tarefa.</p>
                        </div>
                    )}
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Título</label>
                        <input type="text" name="title" value={formState.title} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" disabled={availablePartnerships.length === 0} />
                    </div>
                     <div>
                        <label className="block text-sm font-medium text-gray-700">Descrição</label>
                        <textarea name="description" value={formState.description} onChange={handleChange} rows={3} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" disabled={availablePartnerships.length === 0}></textarea>
                    </div>
                     <div>
                        <label className="block text-sm font-medium text-gray-700">Atribuído a</label>
                        <select multiple name="assignedTo" value={formState.assignedTo} onChange={handleUserChange} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm h-24" disabled={availablePartnerships.length === 0}>
                            {users.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
                        </select>
                        <p className="text-xs text-gray-500 mt-1">Segure Ctrl (ou Cmd no Mac) para selecionar múltiplos.</p>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Data de Vencimento</label>
                        <input type="date" name="dueDate" value={formState.dueDate} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" disabled={availablePartnerships.length === 0} />
                    </div>
                </div>
            </form>
        </Modal>
    );
};

export default NewTaskModal;

