import React, { useState, useMemo, useEffect } from 'react';
import { Task, Partnership, PartnershipStatus, User } from '../types';
import { TrashIcon, PencilIcon, ArrowRightIcon, ViewGridIcon, ViewListIcon } from './Icons';

interface TaskViewProps {
    tasks: Task[];
    partnerships: Partnership[];
    users: User[];
    onNewTask: () => void;
    onCompleteTask: (taskId: string) => void;
    onDeleteTask?: (taskId: string) => void;
    onEditTask: (task: Task) => void;
    highlightedTaskId?: string | null;
    onSelectPartnership?: (partnership: Partnership) => void;
    currentUser?: User;
}

const TaskView: React.FC<TaskViewProps> = ({ tasks, partnerships, users, onNewTask, onCompleteTask, onDeleteTask, onEditTask, highlightedTaskId, onSelectPartnership, currentUser }) => {

    const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');

    const canCreateTask = partnerships.some(p => 
        p.status !== PartnershipStatus.Finished && p.status !== PartnershipStatus.Rejected
    );
    const isConsultant = currentUser?.role === 'Consulta';

    // Filters State
    const [partnershipFilter, setPartnershipFilter] = useState('');
    const [responsibleFilter, setResponsibleFilter] = useState('');
    const [platformFilter, setPlatformFilter] = useState('');
    const [statusFilter, setStatusFilter] = useState('pending'); // Default to pending
    const [dateStartFilter, setDateStartFilter] = useState('');
    const [dateEndFilter, setDateEndFilter] = useState('');

    useEffect(() => {
        if (highlightedTaskId) {
            // Wait a tick for rendering
            setTimeout(() => {
                const element = document.getElementById(`task-${highlightedTaskId}`);
                if (element) {
                    element.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    // If task is highlighted, maybe force grid view or handle row highlight
                }
            }, 100);
        }
    }, [highlightedTaskId, tasks, viewMode]);

    const filteredTasks = useMemo(() => {
        return tasks.filter(task => {
            // Role Based Restriction: Consultants only see tasks assigned to them
            if (isConsultant && currentUser) {
                const isAssignedToMe = task.assignedTo.some(u => u.id === currentUser.id);
                if (!isAssignedToMe) return false;
            }

            const partnership = partnerships.find(p => p.id === task.partnershipId);

            // Partnership Filter
            if (partnershipFilter && task.partnershipId !== partnershipFilter) return false;

            // Responsible Filter
            if (responsibleFilter && !task.assignedTo.some(u => u.id === responsibleFilter)) return false;

            // Platform Filter (Checks if any assigned user has the platform)
            if (platformFilter) {
                const hasPlatform = task.assignedTo.some(u => 
                    u.platform && u.platform.toLowerCase().includes(platformFilter.toLowerCase())
                );
                if (!hasPlatform) return false;
            }

            // Status Filter
            if (statusFilter) {
                if (statusFilter === 'pending' && task.completed) return false;
                if (statusFilter === 'completed' && !task.completed) return false;
            }

            // Date Range Filter (Due Date)
            // Parse task date at midnight for fair comparison
            const taskDate = new Date(task.dueDate);
            taskDate.setHours(0,0,0,0);

            if (dateStartFilter) {
                const startDate = new Date(dateStartFilter);
                if (taskDate < startDate) return false;
            }
            if (dateEndFilter) {
                const endDate = new Date(dateEndFilter);
                if (taskDate > endDate) return false;
            }

            return true;
        }).sort((a,b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime());
    }, [tasks, partnerships, partnershipFilter, responsibleFilter, platformFilter, statusFilter, dateStartFilter, dateEndFilter, isConsultant, currentUser]);


    return (
        <div className="w-full">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <h2 className="text-2xl font-semibold text-gray-700">Gestão de Tarefas</h2>

                <div className="flex items-center gap-3">
                    <div className="flex bg-gray-200 rounded-md p-1">
                        <button 
                            onClick={() => setViewMode('grid')}
                            className={`p-1.5 rounded ${viewMode === 'grid' ? 'bg-white shadow text-teal-600' : 'text-gray-500 hover:text-gray-700'}`}
                            title="Visualização em Grade"
                        >
                            <ViewGridIcon className="w-5 h-5"/>
                        </button>
                        <button 
                            onClick={() => setViewMode('list')}
                            className={`p-1.5 rounded ${viewMode === 'list' ? 'bg-white shadow text-teal-600' : 'text-gray-500 hover:text-gray-700'}`}
                            title="Visualização em Lista"
                        >
                            <ViewListIcon className="w-5 h-5"/>
                        </button>
                    </div>

                    {!isConsultant && (
                        <button 
                            onClick={onNewTask}
                            className="px-4 py-2 bg-teal-600 text-white rounded-md hover:bg-teal-700 disabled:bg-gray-400 disabled:cursor-not-allowed"
                            disabled={!canCreateTask}
                            title={!canCreateTask ? "Não há parcerias ativas para adicionar novas tarefas." : "Criar uma nova tarefa"}
                        >
                            Nova Tarefa
                        </button>
                    )}
                </div>
            </div>

            {/* Filters */}
            <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-200 mb-6">
                <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-6 gap-4">
                    {/* Partnership Filter */}
                    <div>
                        <label className="block text-xs font-medium text-gray-500 mb-1">Parceria</label>
                        <select 
                            value={partnershipFilter} 
                            onChange={(e) => setPartnershipFilter(e.target.value)} 
                            className="block w-full border border-gray-300 rounded-md shadow-sm py-1.5 px-3 text-sm focus:ring-teal-500 focus:border-teal-500"
                        >
                            <option value="">Todas</option>
                            {partnerships.map(p => (
                                <option key={p.id} value={p.id}>{p.reference}</option>
                            ))}
                        </select>
                    </div>

                    {/* Responsible Filter (Hidden/Filtered for Consultants if desired, but user can filter self) */}
                    <div>
                        <label className="block text-xs font-medium text-gray-500 mb-1">Responsável</label>
                        <select 
                            value={responsibleFilter} 
                            onChange={(e) => setResponsibleFilter(e.target.value)} 
                            className="block w-full border border-gray-300 rounded-md shadow-sm py-1.5 px-3 text-sm focus:ring-teal-500 focus:border-teal-500"
                        >
                            <option value="">Todos</option>
                            {users.map(u => (
                                <option key={u.id} value={u.id}>{u.name}</option>
                            ))}
                        </select>
                    </div>

                     {/* Platform Filter */}
                     <div>
                        <label className="block text-xs font-medium text-gray-500 mb-1">Plataforma</label>
                         <input
                            type="text"
                            placeholder="Buscar plataforma..."
                            value={platformFilter}
                            onChange={(e) => setPlatformFilter(e.target.value)}
                            className="block w-full border border-gray-300 rounded-md shadow-sm py-1.5 px-3 text-sm focus:ring-teal-500 focus:border-teal-500"
                        />
                    </div>

                    {/* Status Filter */}
                    <div>
                        <label className="block text-xs font-medium text-gray-500 mb-1">Status</label>
                        <select 
                            value={statusFilter} 
                            onChange={(e) => setStatusFilter(e.target.value)} 
                            className="block w-full border border-gray-300 rounded-md shadow-sm py-1.5 px-3 text-sm focus:ring-teal-500 focus:border-teal-500"
                        >
                            <option value="">Todos</option>
                            <option value="pending">Pendentes</option>
                            <option value="completed">Concluídas</option>
                        </select>
                    </div>

                    {/* Date Start */}
                    <div>
                        <label className="block text-xs font-medium text-gray-500 mb-1">Vencimento (Início)</label>
                        <input 
                            type="date" 
                            value={dateStartFilter} 
                            onChange={(e) => setDateStartFilter(e.target.value)} 
                            className="block w-full border border-gray-300 rounded-md shadow-sm py-1.5 px-3 text-sm focus:ring-teal-500 focus:border-teal-500"
                        />
                    </div>

                    {/* Date End */}
                    <div>
                        <label className="block text-xs font-medium text-gray-500 mb-1">Vencimento (Fim)</label>
                        <input 
                            type="date" 
                            value={dateEndFilter} 
                            onChange={(e) => setDateEndFilter(e.target.value)} 
                            className="block w-full border border-gray-300 rounded-md shadow-sm py-1.5 px-3 text-sm focus:ring-teal-500 focus:border-teal-500"
                        />
                    </div>
                </div>
            </div>

            {/* --- GRID VIEW --- */}
            {viewMode === 'grid' && (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                    {filteredTasks.map(task => {
                        const partnership = partnerships.find(p => p.id === task.partnershipId);
                        const isOverdue = !task.completed && new Date(task.dueDate) < new Date();
                        const isHighlighted = task.id === highlightedTaskId;

                        return (
                            <div 
                                key={task.id} 
                                id={`task-${task.id}`}
                                className={`bg-white rounded-lg shadow-md p-5 border-l-4 transition-all duration-500 ${
                                task.completed ? 'border-lime-500' : isOverdue ? 'border-red-500' : 'border-teal-500'
                            } ${isHighlighted ? 'ring-2 ring-yellow-400 bg-yellow-50' : ''}`}
                            >
                                <div className="flex justify-between items-start">
                                    <h3 className="font-semibold text-gray-800">{task.title}</h3>
                                    <div className="flex space-x-1">
                                        {task.completed ? (
                                            <span className="px-2 py-1 text-xs font-semibold text-lime-800 bg-lime-100 rounded-full">Concluída</span>
                                        ) : (
                                            <span className={`px-2 py-1 text-xs font-semibold ${isOverdue ? 'text-red-800 bg-red-100' : 'text-teal-800 bg-teal-100'} rounded-full`}>Pendente</span>
                                        )}
                                        {!isConsultant && (
                                            <>
                                                <button onClick={() => onEditTask(task)} className="text-teal-600 hover:text-teal-800 p-1" title="Editar Tarefa">
                                                    <PencilIcon className="w-4 h-4" />
                                                </button>
                                                {onDeleteTask && (
                                                    <button onClick={() => onDeleteTask(task.id)} className="text-red-400 hover:text-red-600 p-1">
                                                        <TrashIcon className="w-4 h-4"/>
                                                    </button>
                                                )}
                                            </>
                                        )}
                                    </div>
                                </div>

                                {/* Partnership Reference Link */}
                                <div className="mt-2">
                                    <span className="text-xs text-gray-500">Parceria: </span>
                                    {partnership ? (
                                        onSelectPartnership ? (
                                            <button 
                                                onClick={() => onSelectPartnership(partnership)}
                                                className="text-sm text-teal-600 font-medium hover:underline focus:outline-none"
                                                title="Acessar Detalhes da Parceria"
                                            >
                                                {partnership.reference}
                                            </button>
                                        ) : (
                                            <span className="text-sm font-medium text-gray-700">{partnership.reference}</span>
                                        )
                                    ) : (
                                        <span className="text-sm text-gray-400">N/A</span>
                                    )}
                                </div>

                                <p className="text-sm text-gray-600 mt-2">{task.description}</p>

                                <div className="mt-4">
                                    <p className="text-xs text-gray-500 font-medium">Responsáveis:</p>
                                    <div className="flex flex-wrap gap-1 mt-1">
                                        {task.assignedTo.map(user => (
                                            <span key={user.id} className="text-xs bg-gray-200 text-gray-700 px-2 py-0.5 rounded-full" title={user.platform ? `Plataforma: ${user.platform}` : ''}>
                                                {user.name}
                                            </span>
                                        ))}
                                    </div>
                                </div>

                                <div className="flex justify-between items-end mt-4 text-xs text-gray-500">
                                    <div>
                                        <p>Vencimento: {new Date(task.dueDate).toLocaleDateString()}</p>
                                        {task.completed && task.completionDate && (
                                            <p className="text-lime-600">Concluído em: {new Date(task.completionDate).toLocaleDateString()}</p>
                                        )}
                                    </div>

                                    {!task.completed && (
                                        <button 
                                            onClick={() => onCompleteTask(task.id)}
                                            className="px-3 py-1 bg-lime-500 text-white text-xs rounded hover:bg-lime-600">
                                            Concluir
                                        </button>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}

            {/* --- LIST VIEW --- */}
            {viewMode === 'list' && (
                <div className="bg-white shadow-md rounded-lg overflow-x-auto">
                    <table className="min-w-full divide-y divide-gray-200">
                        <thead className="bg-gray-50">
                            <tr>
                                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Título / Descrição</th>
                                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Parceria</th>
                                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Responsáveis</th>
                                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Vencimento</th>
                                <th scope="col" className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Ações</th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                            {filteredTasks.map(task => {
                                const partnership = partnerships.find(p => p.id === task.partnershipId);
                                const isOverdue = !task.completed && new Date(task.dueDate) < new Date();
                                const isHighlighted = task.id === highlightedTaskId;

                                return (
                                    <tr 
                                        key={task.id} 
                                        id={`task-${task.id}`}
                                        className={`hover:bg-gray-50 ${isHighlighted ? 'bg-yellow-50' : ''}`}
                                    >
                                        <td className="px-6 py-4 whitespace-nowrap">
                                             {task.completed ? (
                                                <span className="px-2 py-1 text-xs font-semibold text-lime-800 bg-lime-100 rounded-full">Concluída</span>
                                            ) : (
                                                <span className={`px-2 py-1 text-xs font-semibold ${isOverdue ? 'text-red-800 bg-red-100' : 'text-teal-800 bg-teal-100'} rounded-full`}>Pendente</span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="text-sm font-medium text-gray-900">{task.title}</div>
                                            <div className="text-xs text-gray-500 truncate max-w-xs">{task.description}</div>
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                            {partnership ? (
                                                onSelectPartnership ? (
                                                    <button 
                                                        onClick={() => onSelectPartnership(partnership)}
                                                        className="text-teal-600 hover:underline focus:outline-none font-medium"
                                                    >
                                                        {partnership.reference}
                                                    </button>
                                                ) : (
                                                    partnership.reference
                                                )
                                            ) : (
                                                <span className="text-gray-400">N/A</span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="flex flex-wrap gap-1">
                                                {task.assignedTo.map(user => (
                                                    <span key={user.id} className="text-xs bg-gray-100 text-gray-700 px-2 py-0.5 rounded border">
                                                        {user.name}
                                                    </span>
                                                ))}
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                            <div>{new Date(task.dueDate).toLocaleDateString()}</div>
                                            {task.completed && task.completionDate && (
                                                <div className="text-xs text-lime-600">Concluído: {new Date(task.completionDate).toLocaleDateString()}</div>
                                            )}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                                            <div className="flex justify-end items-center space-x-2">
                                                {!task.completed && (
                                                    <button 
                                                        onClick={() => onCompleteTask(task.id)}
                                                        className="px-2 py-1 bg-lime-500 text-white text-xs rounded hover:bg-lime-600">
                                                        Concluir
                                                    </button>
                                                )}
                                                {!isConsultant && (
                                                    <>
                                                        <button onClick={() => onEditTask(task)} className="text-teal-600 hover:text-teal-900 p-1" title="Editar">
                                                            <PencilIcon className="w-4 h-4" />
                                                        </button>
                                                        {onDeleteTask && (
                                                            <button onClick={() => onDeleteTask(task.id)} className="text-red-400 hover:text-red-600 p-1" title="Excluir">
                                                                <TrashIcon className="w-4 h-4"/>
                                                            </button>
                                                        )}
                                                    </>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
            )}

            {filteredTasks.length === 0 && (
                <p className="text-sm text-gray-500 col-span-full text-center mt-6">Nenhuma tarefa encontrada com os filtros selecionados.</p>
            )}
        </div>
    );
};

export default TaskView;

export enum PartnershipStatus {
    Negotiating = 'Em negociação',
    Executing = 'Em execução',
    Rejected = 'Indeferido',
    Finished = 'Finalizado',
    Edict = 'Edital',
}

export enum ProjectType {
    CoDevelopment = 'Codesenvolvimento',
    Service = 'Prestação de Serviços',
    Institutional = 'Institucional',
    Embrapii = 'Embrapii',
    Edicts = 'Editais',
}

export enum LegalInstrumentType {
    PartnershipAgreement = 'Acordo de Parceria',
    ServiceAgreement = 'Prestação de Serviços',
    ServiceContract = 'Contratação de Serviços',
    MOU = 'Memorando de Entendimento',
    StrategicAlliance = 'Aliança estratégica',
    NDA = 'NDA',
    ManagementSheet = 'Ficha de Gestão',
    SIEX = 'SIEX',
    PatentKnowHow = 'Patente/Know-how',
    Other = 'Outros',
}

export enum View {
    Dashboard = 'Dashboard',
    Partnerships = 'Parcerias',
    LegalInstruments = 'Instrumentos Jurídicos',
    Tasks = 'Tarefas',
    Settings = 'Configurações',
}

export type SyncStatus = 'idle' | 'loading' | 'saving' | 'synced' | 'error';

export interface User {
    id: string;
    name: string;
    email: string;
    role: 'Coordenador' | 'Pesquisador' | 'Administrador' | 'Consulta';
    platform?: string;
}

export interface Partner {
    id: string;
    name:string;
    coordinator: string;
}

export interface HistoryEntry {
    id: string; // Added ID for read tracking
    date: string;
    description: string;
    user: string;
    link?: string;
}

export interface UploadedFile {
    id: string;
    file: { name: string; };
    observations: string;
    user: string;
    date: string;
    webUrl?: string;
}

export interface Partnership {
    id: string;
    reference: string;
    status: PartnershipStatus;
    title: string;
    funder: string;
    funderCoordinator: string;
    partners: Partner[];
    ctvCoordinator: User;
    ctvResearcher: User;
    ctvBusinessPartner: User;
    entryDate: string;
    executionStartDate: string;
    approvedValue: number;
    projectType: ProjectType;
    folderWebUrl?: string;
    folderId?: string;
    linkedInstrumentIds: number[];
    observations: string[];
    projectNumber: string;
    history: HistoryEntry[];
    documents: UploadedFile[];
    confidential?: boolean;
}

export interface LegalInstrumentAddendum {
    id: string;
    signatureDate: string;
    newExpirationDate: string;
    documentWebUrl?: string;
}

export interface LegalInstrument {
    id: number;
    signatories: string[];
    type: LegalInstrumentType;
    linkedPartnershipIds: string[];
    object: string;
    signatureDate: string;
    expirationDate: string;
    document?: { name: string };
    documentWebUrl?: string;
    folderId?: string;
    folderWebUrl?: string;
    observations: string;
    addendums: LegalInstrumentAddendum[];
}

export interface Task {
    id: string;
    partnershipId: string;
    title: string;
    description: string;
    assignedTo: User[];
    dueDate: string;
    completed: boolean;
    completedBy?: string;
    completionDate?: string;
    createdBy: string;
    creationDate: string;
}

export interface Notification {
    id: string;
    recipient: string;
    subject: string;
    body: string;
    timestamp: string;
    read: boolean;
    link?: {
        view: View;
        partnershipId: string;
        instrumentId?: number;
    };
}

export interface SystemSettings {
    senderEmail: string;
}

export interface AppState {
    users: User[];
    partnerships: Partnership[];
    legalInstruments: LegalInstrument[];
    tasks: Task[];
    sentExpirationWarnings: Record<string, { sixty?: boolean, thirty?: boolean, seven?: boolean }>;
    systemSettings: SystemSettings;
    readHistoryIds?: string[]; // Added to persist read history
}

import React, { useState, useEffect, useRef } from 'react';
import { LegalInstrument, Partnership, LegalInstrumentType } from '../types';
import Modal from './Modal';
import { PlusIcon, TrashIcon, UploadIcon, SearchIcon, XIcon } from './Icons';

interface NewLegalInstrumentModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (instrument: Omit<LegalInstrument, 'id' | 'addendums'>, file: File | null) => Promise<void>;
    partnerships: Partnership[];
    isSubmitting: boolean;
    preSelectedPartnership?: Partnership | null;
    instrumentToEdit?: LegalInstrument | null;
}

const initialState = {
    signatories: [''],
    type: LegalInstrumentType.PartnershipAgreement,
    linkedPartnershipIds: [] as string[],
    object: '',
    signatureDate: new Date().toISOString().split('T')[0],
    expirationDate: '',
    document: undefined,
    observations: '',
};

const NewLegalInstrumentModal: React.FC<NewLegalInstrumentModalProps> = ({ isOpen, onClose, onSubmit, partnerships, isSubmitting, preSelectedPartnership, instrumentToEdit }) => {
    const [formState, setFormState] = useState<Omit<LegalInstrument, 'id' | 'addendums'>>(initialState);
    const [file, setFile] = useState<File | null>(null);

    // Searchable dropdown states
    const [searchTerm, setSearchTerm] = useState('');
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    const isEditing = !!instrumentToEdit;

    useEffect(() => {
        if (isOpen) {
            if (instrumentToEdit) {
                setFormState({
                    signatories: instrumentToEdit.signatories,
                    type: instrumentToEdit.type,
                    linkedPartnershipIds: instrumentToEdit.linkedPartnershipIds,
                    object: instrumentToEdit.object,
                    signatureDate: instrumentToEdit.signatureDate,
                    expirationDate: instrumentToEdit.expirationDate,
                    document: instrumentToEdit.document,
                    observations: instrumentToEdit.observations,
                });
            } else {
                setFormState({
                    ...initialState,
                    linkedPartnershipIds: preSelectedPartnership ? [preSelectedPartnership.id] : [],
                });
            }
            setFile(null);
            setSearchTerm('');
            setIsDropdownOpen(false);
        }
    }, [isOpen, preSelectedPartnership, instrumentToEdit]);

    // Handle click outside to close dropdown
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormState(prev => ({ ...prev, [name]: value }));
    };

    const togglePartnership = (partnershipId: string) => {
        setFormState(prev => {
            const isSelected = prev.linkedPartnershipIds.includes(partnershipId);
            const newIds = isSelected 
                ? prev.linkedPartnershipIds.filter(id => id !== partnershipId)
                : [...prev.linkedPartnershipIds, partnershipId];
            return { ...prev, linkedPartnershipIds: newIds };
        });
        setSearchTerm('');
        setIsDropdownOpen(false);
    };

    const handleSignatoryChange = (index: number, value: string) => {
        const newSignatories = [...formState.signatories];
        newSignatories[index] = value;
        setFormState(prev => ({ ...prev, signatories: newSignatories }));
    };

    const addSignatory = () => {
        setFormState(prev => ({ ...prev, signatories: [...prev.signatories, ''] }));
    };

    const removeSignatory = (index: number) => {
        setFormState(prev => ({ ...prev, signatories: prev.signatories.filter((_, i) => i !== index) }));
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            setFile(e.target.files[0]);
        } else {
            setFile(null);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (formState.linkedPartnershipIds.length === 0) {
            alert("Por favor, selecione pelo menos uma parceria para vincular.");
            return;
        }
        await onSubmit(formState, file);
    };

    // Filtering logic for the search
    const filteredPartnerships = partnerships.filter(p => {
        const matchesSearch = p.reference.toLowerCase().includes(searchTerm.toLowerCase()) || 
                             p.title.toLowerCase().includes(searchTerm.toLowerCase());
        const notSelected = !formState.linkedPartnershipIds.includes(p.id);
        return matchesSearch && notSelected;
    });

    const selectedPartnershipsData = partnerships.filter(p => formState.linkedPartnershipIds.includes(p.id));

    return (
        <Modal isOpen={isOpen} onClose={onClose} title={isEditing ? 'Editar Instrumento Jurídico' : 'Criar Novo Instrumento Jurídico'}>
            <form onSubmit={handleSubmit}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {/* Header Fields */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Tipo</label>
                        <select name="type" value={formState.type} onChange={handleChange} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm">
                            {Object.values(LegalInstrumentType).map(t => <option key={t} value={t}>{t}</option>)}
                        </select>
                    </div>

                    {/* Searchable Partnership Multi-select */}
                    <div className="md:row-span-2">
                        <label className="block text-sm font-medium text-gray-700 mb-1">Vincular Parcerias (Busca por texto)</label>
                        <div className="relative" ref={dropdownRef}>
                            <div className="relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                    <SearchIcon className="h-4 w-4 text-gray-400" />
                                </div>
                                <input
                                    type="text"
                                    placeholder="Digite a referência ou nome da parceria..."
                                    value={searchTerm}
                                    onChange={(e) => {
                                        setSearchTerm(e.target.value);
                                        setIsDropdownOpen(true);
                                    }}
                                    onFocus={() => setIsDropdownOpen(true)}
                                    className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm"
                                />
                            </div>

                            {isDropdownOpen && (
                                <ul className="absolute z-20 mt-1 w-full bg-white shadow-lg max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
                                    {filteredPartnerships.length === 0 ? (
                                        <li className="text-gray-500 cursor-default select-none relative py-2 px-3">
                                            {searchTerm ? 'Nenhuma parceria encontrada.' : 'Comece a digitar para buscar...'}
                                        </li>
                                    ) : (
                                        filteredPartnerships.map((p) => (
                                            <li
                                                key={p.id}
                                                className="cursor-pointer select-none relative py-2 pl-3 pr-9 hover:bg-teal-50 text-gray-900 border-b border-gray-50 last:border-0"
                                                onClick={() => togglePartnership(p.id)}
                                            >
                                                <div className="flex flex-col">
                                                    <span className="font-bold text-teal-700">{p.reference}</span>
                                                    <span className="text-xs text-gray-500 truncate">{p.title}</span>
                                                </div>
                                            </li>
                                        ))
                                    )}
                                </ul>
                            )}
                        </div>

                        {/* Selected Items Pills */}
                        <div className="mt-3 flex flex-wrap gap-2">
                            {selectedPartnershipsData.length > 0 ? (
                                selectedPartnershipsData.map(p => (
                                    <div key={p.id} className="inline-flex items-center bg-teal-50 text-teal-800 text-xs font-semibold px-2.5 py-1 rounded-full border border-teal-200">
                                        <span className="max-w-[150px] truncate">{p.reference}</span>
                                        <button 
                                            type="button" 
                                            onClick={() => togglePartnership(p.id)}
                                            className="ml-1.5 inline-flex items-center justify-center text-teal-400 hover:text-teal-600 focus:outline-none"
                                        >
                                            <XIcon className="h-3 w-3" />
                                        </button>
                                    </div>
                                ))
                            ) : (
                                <span className="text-xs text-red-500 italic">Nenhuma parceria selecionada.</span>
                            )}
                        </div>
                    </div>

                    <div className="md:col-span-1">
                         <label className="block text-sm font-medium text-gray-700">Data de Assinatura</label>
                        <input type="date" name="signatureDate" value={formState.signatureDate} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-700">Data de Vigência</label>
                        <input type="date" name="expirationDate" value={formState.expirationDate} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" />
                    </div>

                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700">Objeto</label>
                        <textarea name="object" value={formState.object} onChange={handleChange} rows={3} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm"></textarea>
                    </div>

                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700">Observações</label>
                        <textarea name="observations" value={formState.observations} onChange={handleChange} rows={2} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm"></textarea>
                    </div>

                    {/* Signatories */}
                    <div className="md:col-span-2">
                         <label className="block text-sm font-medium text-gray-700">Signatários</label>
                         {formState.signatories.map((s, index) => (
                             <div key={index} className="flex items-center space-x-2 mt-1">
                                 <input type="text" value={s} onChange={e => handleSignatoryChange(index, e.target.value)} required className="block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" placeholder={`Signatário ${index + 1}`} />
                                 {formState.signatories.length > 1 && (
                                     <button type="button" onClick={() => removeSignatory(index)} className="text-red-500 hover:text-red-700 p-1">
                                        <TrashIcon className="w-5 h-5"/>
                                     </button>
                                 )}
                             </div>
                         ))}
                         <button type="button" onClick={addSignatory} className="text-sm text-teal-600 hover:text-teal-800 mt-2 flex items-center">
                            <PlusIcon className="w-4 h-4 mr-1"/>
                            Adicionar Signatário
                         </button>
                    </div>

                     {/* File Upload */}
                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700">Documento Principal {isEditing && '(Opcional se já existir)'}</label>
                        <div className="mt-1 flex items-center justify-center px-6 pt-5 pb-6 border-2 border-gray-300 border-dashed rounded-md">
                            <div className="space-y-1 text-center">
                                <UploadIcon className="mx-auto h-12 w-12 text-gray-400" />
                                <div className="flex text-sm text-gray-600">
                                    <label htmlFor="file-upload" className="relative cursor-pointer bg-white rounded-md font-medium text-teal-600 hover:text-teal-500 focus-within:outline-none focus-within:ring-2 focus-within:ring-offset-2 focus-within:ring-teal-500">
                                        <span>Carregar um arquivo</span>
                                        <input id="file-upload" name="file-upload" type="file" className="sr-only" onChange={handleFileChange} />
                                    </label>
                                </div>
                                {file ? (
                                    <p className="text-sm text-gray-500">{file.name}</p>
                                ) : (
                                    <p className="text-xs text-gray-500">PDF, DOCX, etc.</p>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
                 <div className="flex justify-end items-center pt-4 border-t space-x-2 mt-6">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300" disabled={isSubmitting}>Cancelar</button>
                    <button type="submit" className="px-4 py-2 bg-teal-600 text-white rounded-md hover:bg-teal-700 disabled:bg-teal-300" disabled={isSubmitting}>
                        {isSubmitting ? 'Salvando...' : (isEditing ? 'Salvar Alterações' : 'Salvar Instrumento')}
                    </button>
                </div>
            </form>
        </Modal>
    );
};

export default NewLegalInstrumentModal;

import React, { useState, useEffect, useCallback } from 'react';
import { v4 as uuidv4 } from '../utils/uuid';
import { Partnership, User, PartnershipStatus, ProjectType } from '../types';
import Modal from './Modal';
import { PlusIcon, TrashIcon } from './Icons';

interface NewPartnershipModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (partnership: Omit<Partnership, 'id' | 'history' | 'documents' | 'linkedInstrumentIds' | 'folderWebUrl' | 'folderId'>) => void;
    users: User[];
    isSubmitting: boolean;
    isMicrosoftSignedIn: boolean;
    partnershipToEdit?: Partnership | null;
}

const NewPartnershipModal: React.FC<NewPartnershipModalProps> = ({ isOpen, onClose, onSubmit, users, isSubmitting, isMicrosoftSignedIn, partnershipToEdit }) => {
    const isEditing = !!partnershipToEdit;

    const getInitialState = useCallback(() => {
        const defaultState = {
            reference: '',
            status: PartnershipStatus.Negotiating,
            title: '',
            funder: '',
            funderCoordinator: '',
            partners: [],
            ctvCoordinator: users.find(u => u.role === 'Coordenador') || users[0],
            ctvResearcher: users[0],
            ctvBusinessPartner: users[0],
            entryDate: new Date().toISOString().split('T')[0],
            executionStartDate: '',
            approvedValue: 0,
            projectType: ProjectType.CoDevelopment,
            observations: [''],
            projectNumber: '',
            confidential: false,
        };

        if (isEditing && partnershipToEdit) {
            return {
                reference: partnershipToEdit.reference,
                status: partnershipToEdit.status,
                title: partnershipToEdit.title,
                funder: partnershipToEdit.funder,
                funderCoordinator: partnershipToEdit.funderCoordinator,
                partners: partnershipToEdit.partners,
                ctvCoordinator: partnershipToEdit.ctvCoordinator,
                ctvResearcher: partnershipToEdit.ctvResearcher,
                ctvBusinessPartner: partnershipToEdit.ctvBusinessPartner,
                entryDate: partnershipToEdit.entryDate,
                executionStartDate: partnershipToEdit.executionStartDate,
                approvedValue: partnershipToEdit.approvedValue,
                projectType: partnershipToEdit.projectType,
                observations: partnershipToEdit.observations,
                projectNumber: partnershipToEdit.projectNumber,
                confidential: partnershipToEdit.confidential || false,
            };
        }
        return defaultState;
    }, [isEditing, partnershipToEdit, users]);

    const [formState, setFormState] = useState(getInitialState());

    useEffect(() => {
        if(isOpen) {
            setFormState(getInitialState());
        }
    }, [isOpen, getInitialState]);


    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value, type } = e.target;
        if (type === 'checkbox') {
             const checked = (e.target as HTMLInputElement).checked;
             setFormState(prev => ({ ...prev, [name]: checked }));
        } else {
             setFormState(prev => ({ ...prev, [name]: name === 'approvedValue' ? parseFloat(value) || 0 : value }));
        }
    };

    const handleUserChange = (e: React.ChangeEvent<HTMLSelectElement>, field: 'ctvCoordinator' | 'ctvResearcher' | 'ctvBusinessPartner') => {
        const selectedUser = users.find(u => u.id === e.target.value);
        if (selectedUser) {
            setFormState(prev => ({ ...prev, [field]: selectedUser }));
        }
    };

    const addPartner = () => {
        setFormState(prev => ({ ...prev, partners: [...prev.partners, { id: uuidv4(), name: '', coordinator: '' }] }));
    };

    const removePartner = (id: string) => {
        setFormState(prev => ({ ...prev, partners: prev.partners.filter(p => p.id !== id) }));
    };

    const handlePartnerChange = (id: string, field: 'name' | 'coordinator', value: string) => {
        setFormState(prev => ({
            ...prev,
            partners: prev.partners.map(p => p.id === id ? { ...p, [field]: value } : p)
        }));
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSubmit(formState);
        if(!isSubmitting){
            setFormState(getInitialState());
        }
    };

    const coordinators = users.filter(u => u.role === 'Coordenador');
    // We allow any user to be assigned to researcher and business partner roles for maximum flexibility
    const allAvailableUsers = [...users].sort((a, b) => a.name.localeCompare(b.name));

    return (
        <Modal isOpen={isOpen} onClose={onClose} title={isEditing ? 'Editar Parceria' : 'Criar Nova Parceria'}>
            <form onSubmit={handleSubmit}>
                {!isMicrosoftSignedIn && (
                    <div className="p-3 mb-4 text-sm text-yellow-700 bg-yellow-100 border border-yellow-200 rounded-md">
                        Aviso: A conexão com o SharePoint falhou. A pasta do projeto não será criada na nuvem.
                    </div>
                )}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Referência</label>
                        <input type="text" name="reference" value={formState.reference} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Título do Projeto/Parceria</label>
                        <input type="text" name="title" value={formState.title} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Status</label>
                        <select name="status" value={formState.status} onChange={handleChange} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm">
                            {Object.values(PartnershipStatus).map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                    </div>
                     <div>
                        <label className="block text-sm font-medium text-gray-700">Tipo de Projeto</label>
                        <select name="projectType" value={formState.projectType} onChange={handleChange} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm">
                            {Object.values(ProjectType).map(t => <option key={t} value={t}>{t}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Financiador</label>
                        <input type="text" name="funder" value={formState.funder} onChange={handleChange} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Coordenador do Financiador</label>
                        <input type="text" name="funderCoordinator" value={formState.funderCoordinator} onChange={handleChange} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Coordenador CTV</label>
                        <select name="ctvCoordinator" value={formState.ctvCoordinator.id} onChange={(e) => handleUserChange(e, 'ctvCoordinator')} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm">
                            {coordinators.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                        </select>
                    </div>
                     <div>
                        <label className="block text-sm font-medium text-gray-700">Pesquisador Responsável CTV</label>
                        <select name="ctvResearcher" value={formState.ctvResearcher.id} onChange={(e) => handleUserChange(e, 'ctvResearcher')} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm">
                            {allAvailableUsers.map(r => <option key={r.id} value={r.id}>{r.name} ({r.role})</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Negócios e Parcerias</label>
                        <select name="ctvBusinessPartner" value={formState.ctvBusinessPartner.id} onChange={(e) => handleUserChange(e, 'ctvBusinessPartner')} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm">
                            {allAvailableUsers.map(bp => <option key={bp.id} value={bp.id}>{bp.name} ({bp.role})</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Data de Entrada</label>
                        <input type="date" name="entryDate" value={formState.entryDate} onChange={handleChange} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Início da Execução</label>
                        <input type="date" name="executionStartDate" value={formState.executionStartDate} onChange={handleChange} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" />
                    </div>
                    <div className="md:col-span-1">
                        <label className="block text-sm font-medium text-gray-700">Valor Aprovado (R$)</label>
                        <input type="number" name="approvedValue" value={formState.approvedValue} onChange={handleChange} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" />
                    </div>
                    <div className="md:col-span-1">
                        <label className="block text-sm font-medium text-gray-700">Número do Projeto</label>
                        <input type="text" name="projectNumber" value={formState.projectNumber} onChange={handleChange} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" />
                    </div>
                     <div className="md:col-span-2">
                         <div className="flex items-center mt-2">
                             <input
                                id="confidential"
                                name="confidential"
                                type="checkbox"
                                checked={formState.confidential}
                                onChange={handleChange}
                                className="h-4 w-4 text-teal-600 focus:ring-teal-500 border-gray-300 rounded"
                            />
                            <label htmlFor="confidential" className="ml-2 block text-sm text-gray-900 font-semibold">
                                Parceria Confidencial (Acesso restrito apenas aos envolvidos e administradores)
                            </label>
                         </div>
                     </div>
                     <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700">Observações</label>
                        <textarea name="observations" value={formState.observations[0]} onChange={(e) => setFormState(prev => ({...prev, observations: [e.target.value]}))} rows={3} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm"></textarea>
                    </div>

                    <div className="md:col-span-2">
                        <div className="flex justify-between items-center">
                            <h4 className="text-md font-medium text-gray-800">Parceiros Externos</h4>
                            <button type="button" onClick={addPartner} className="flex items-center text-sm text-teal-600 hover:text-teal-800">
                                <PlusIcon className="w-4 h-4 mr-1"/> Adicionar Parceiro
                            </button>
                        </div>
                         <div className="mt-2 space-y-2">
                            {formState.partners.map((partner) => (
                                <div key={partner.id} className="grid grid-cols-1 sm:grid-cols-5 gap-2 items-center p-2 border rounded-md">
                                    <input
                                        type="text"
                                        placeholder="Nome do Parceiro"
                                        value={partner.name}
                                        onChange={(e) => handlePartnerChange(partner.id, 'name', e.target.value)}
                                        className="col-span-2 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 sm:text-sm"
                                    />
                                     <input
                                        type="text"
                                        placeholder="Coordenador do Parceiro"
                                        value={partner.coordinator}
                                        onChange={(e) => handlePartnerChange(partner.id, 'coordinator', e.target.value)}
                                        className="col-span-2 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 sm:text-sm"
                                    />
                                    <button type="button" onClick={() => removePartner(partner.id)} className="text-red-500 hover:text-red-700 justify-self-end">
                                        <TrashIcon />
                                    </button>
                                </div>
                            ))}
                         </div>
                    </div>
                </div>
                 <div className="flex justify-end items-center p-4 border-t space-x-2 mt-6">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300" disabled={isSubmitting}>Cancelar</button>
                    <button type="submit" className="px-4 py-2 bg-teal-600 text-white rounded-md hover:bg-teal-700 disabled:bg-teal-300" disabled={isSubmitting}>
                        {isSubmitting ? 'Salvando...' : (isEditing ? 'Salvar Alterações' : 'Salvar Parceria')}
                    </button>
                </div>
            </form>
        </Modal>
    );
};

export default NewPartnershipModal;

import React, { useState, useEffect, useRef } from 'react';
import { LegalInstrument, Partnership, LegalInstrumentType } from '../types';
import Modal from './Modal';
import { PlusIcon, TrashIcon, UploadIcon, SearchIcon, XIcon } from './Icons';

interface NewLegalInstrumentModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (instrument: Omit<LegalInstrument, 'id' | 'addendums'>, file: File | null) => Promise<void>;
    partnerships: Partnership[];
    isSubmitting: boolean;
    preSelectedPartnership?: Partnership | null;
    instrumentToEdit?: LegalInstrument | null;
}

const initialState = {
    signatories: [''],
    type: LegalInstrumentType.PartnershipAgreement,
    linkedPartnershipIds: [] as string[],
    object: '',
    signatureDate: new Date().toISOString().split('T')[0],
    expirationDate: '',
    document: undefined,
    observations: '',
};

const NewLegalInstrumentModal: React.FC<NewLegalInstrumentModalProps> = ({ isOpen, onClose, onSubmit, partnerships, isSubmitting, preSelectedPartnership, instrumentToEdit }) => {
    const [formState, setFormState] = useState<Omit<LegalInstrument, 'id' | 'addendums'>>(initialState);
    const [files, setFiles] = useState<File[]>([]);
    const [isMerging, setIsMerging] = useState(false);

    // Searchable dropdown states
    const [searchTerm, setSearchTerm] = useState('');
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    const isEditing = !!instrumentToEdit;

    useEffect(() => {
        if (isOpen) {
            if (instrumentToEdit) {
                setFormState({
                    signatories: instrumentToEdit.signatories,
                    type: instrumentToEdit.type,
                    linkedPartnershipIds: instrumentToEdit.linkedPartnershipIds,
                    object: instrumentToEdit.object,
                    signatureDate: instrumentToEdit.signatureDate,
                    expirationDate: instrumentToEdit.expirationDate,
                    document: instrumentToEdit.document,
                    observations: instrumentToEdit.observations,
                });
            } else {
                setFormState({
                    ...initialState,
                    linkedPartnershipIds: preSelectedPartnership ? [preSelectedPartnership.id] : [],
                });
            }
            setFiles([]);
            setSearchTerm('');
            setIsDropdownOpen(false);
            setIsMerging(false);
        }
    }, [isOpen, preSelectedPartnership, instrumentToEdit]);

    // Handle click outside to close dropdown
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormState(prev => ({ ...prev, [name]: value }));
    };

    const togglePartnership = (partnershipId: string) => {
        setFormState(prev => {
            const isSelected = prev.linkedPartnershipIds.includes(partnershipId);
            const newIds = isSelected 
                ? prev.linkedPartnershipIds.filter(id => id !== partnershipId)
                : [...prev.linkedPartnershipIds, partnershipId];
            return { ...prev, linkedPartnershipIds: newIds };
        });
        setSearchTerm('');
        setIsDropdownOpen(false);
    };

    const handleSignatoryChange = (index: number, value: string) => {
        const newSignatories = [...formState.signatories];
        newSignatories[index] = value;
        setFormState(prev => ({ ...prev, signatories: newSignatories }));
    };

    const addSignatory = () => {
        setFormState(prev => ({ ...prev, signatories: [...prev.signatories, ''] }));
    };

    const removeSignatory = (index: number) => {
        setFormState(prev => ({ ...prev, signatories: prev.signatories.filter((_, i) => i !== index) }));
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            const newFiles = Array.from(e.target.files);
            setFiles(prev => [...prev, ...newFiles]);
        }
        // Reset input value to allow selecting same file again
        e.target.value = '';
    };

    const removeFile = (index: number) => {
        setFiles(prev => prev.filter((_, i) => i !== index));
    };

    const mergePDFs = async (pdfFiles: File[]): Promise<File> => {
        const { PDFDocument } = (window as any).PDFLib;
        const mergedPdf = await PDFDocument.create();

        for (const file of pdfFiles) {
            const arrayBuffer = await file.arrayBuffer();
            const pdf = await PDFDocument.load(arrayBuffer);
            const copiedPages = await mergedPdf.copyPages(pdf, pdf.getPageIndices());
            copiedPages.forEach((page: any) => mergedPdf.addPage(page));
        }

        const mergedPdfBytes = await mergedPdf.save();
        const mergedFile = new File([mergedPdfBytes], "instrumento_unificado.pdf", { type: 'application/pdf' });
        return mergedFile;
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (formState.linkedPartnershipIds.length === 0) {
            alert("Por favor, selecione pelo menos uma parceria para vincular.");
            return;
        }

        let finalFile: File | null = null;
        if (files.length > 1) {
            setIsMerging(true);
            try {
                // Filter only PDFs for merging
                const onlyPdfs = files.filter(f => f.type === 'application/pdf');
                if (onlyPdfs.length !== files.length) {
                    if (!window.confirm("Atenção: Apenas arquivos PDF serão mesclados. Outros formatos serão descartados no processo de junção. Deseja continuar?")) {
                        setIsMerging(false);
                        return;
                    }
                }
                finalFile = await mergePDFs(onlyPdfs);
            } catch (error) {
                console.error("Erro ao mesclar PDFs:", error);
                alert("Ocorreu um erro ao tentar mesclar os PDFs. Certifique-se de que todos os arquivos são PDFs válidos.");
                setIsMerging(false);
                return;
            } finally {
                setIsMerging(false);
            }
        } else if (files.length === 1) {
            finalFile = files[0];
        }

        await onSubmit(formState, finalFile);
    };

    // Filtering logic for the search
    const filteredPartnerships = partnerships.filter(p => {
        const matchesSearch = p.reference.toLowerCase().includes(searchTerm.toLowerCase()) || 
                             p.title.toLowerCase().includes(searchTerm.toLowerCase());
        const notSelected = !formState.linkedPartnershipIds.includes(p.id);
        return matchesSearch && notSelected;
    });

    const selectedPartnershipsData = partnerships.filter(p => formState.linkedPartnershipIds.includes(p.id));

    return (
        <Modal isOpen={isOpen} onClose={onClose} title={isEditing ? 'Editar Instrumento Jurídico' : 'Criar Novo Instrumento Jurídico'}>
            <form onSubmit={handleSubmit}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {/* Header Fields */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Tipo</label>
                        <select name="type" value={formState.type} onChange={handleChange} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm">
                            {Object.values(LegalInstrumentType).map(t => <option key={t} value={t}>{t}</option>)}
                        </select>
                    </div>

                    {/* Searchable Partnership Multi-select */}
                    <div className="md:row-span-2">
                        <label className="block text-sm font-medium text-gray-700 mb-1">Vincular Parcerias (Busca por texto)</label>
                        <div className="relative" ref={dropdownRef}>
                            <div className="relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                    <SearchIcon className="h-4 w-4 text-gray-400" />
                                </div>
                                <input
                                    type="text"
                                    placeholder="Digite a referência ou nome da parceria..."
                                    value={searchTerm}
                                    onChange={(e) => {
                                        setSearchTerm(e.target.value);
                                        setIsDropdownOpen(true);
                                    }}
                                    onFocus={() => setIsDropdownOpen(true)}
                                    className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm"
                                />
                            </div>

                            {isDropdownOpen && (
                                <ul className="absolute z-20 mt-1 w-full bg-white shadow-lg max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
                                    {filteredPartnerships.length === 0 ? (
                                        <li className="text-gray-500 cursor-default select-none relative py-2 px-3">
                                            {searchTerm ? 'Nenhuma parceria encontrada.' : 'Comece a digitar para buscar...'}
                                        </li>
                                    ) : (
                                        filteredPartnerships.map((p) => (
                                            <li
                                                key={p.id}
                                                className="cursor-pointer select-none relative py-2 pl-3 pr-9 hover:bg-teal-50 text-gray-900 border-b border-gray-50 last:border-0"
                                                onClick={() => togglePartnership(p.id)}
                                            >
                                                <div className="flex flex-col">
                                                    <span className="font-bold text-teal-700">{p.reference}</span>
                                                    <span className="text-xs text-gray-500 truncate">{p.title}</span>
                                                </div>
                                            </li>
                                        ))
                                    )}
                                </ul>
                            )}
                        </div>

                        {/* Selected Items Pills */}
                        <div className="mt-3 flex flex-wrap gap-2">
                            {selectedPartnershipsData.length > 0 ? (
                                selectedPartnershipsData.map(p => (
                                    <div key={p.id} className="inline-flex items-center bg-teal-50 text-teal-800 text-xs font-semibold px-2.5 py-1 rounded-full border border-teal-200">
                                        <span className="max-w-[150px] truncate">{p.reference}</span>
                                        <button 
                                            type="button" 
                                            onClick={() => togglePartnership(p.id)}
                                            className="ml-1.5 inline-flex items-center justify-center text-teal-400 hover:text-teal-600 focus:outline-none"
                                        >
                                            <XIcon className="h-3 w-3" />
                                        </button>
                                    </div>
                                ))
                            ) : (
                                <span className="text-xs text-red-500 italic">Nenhuma parceria selecionada.</span>
                            )}
                        </div>
                    </div>

                    <div className="md:col-span-1">
                         <label className="block text-sm font-medium text-gray-700">Data de Assinatura</label>
                        <input type="date" name="signatureDate" value={formState.signatureDate} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-700">Data de Vigência</label>
                        <input type="date" name="expirationDate" value={formState.expirationDate} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" />
                    </div>

                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700">Objeto</label>
                        <textarea name="object" value={formState.object} onChange={handleChange} rows={3} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm"></textarea>
                    </div>

                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700">Observações</label>
                        <textarea name="observations" value={formState.observations} onChange={handleChange} rows={2} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm"></textarea>
                    </div>

                    {/* Signatories */}
                    <div className="md:col-span-2">
                         <label className="block text-sm font-medium text-gray-700">Signatários</label>
                         {formState.signatories.map((s, index) => (
                             <div key={index} className="flex items-center space-x-2 mt-1">
                                 <input type="text" value={s} onChange={e => handleSignatoryChange(index, e.target.value)} required className="block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" placeholder={`Signatário ${index + 1}`} />
                                 {formState.signatories.length > 1 && (
                                     <button type="button" onClick={() => removeSignatory(index)} className="text-red-500 hover:text-red-700 p-1">
                                        <TrashIcon className="w-5 h-5"/>
                                     </button>
                                 )}
                             </div>
                         ))}
                         <button type="button" onClick={addSignatory} className="text-sm text-teal-600 hover:text-teal-800 mt-2 flex items-center">
                            <PlusIcon className="w-4 h-4 mr-1"/>
                            Adicionar Signatário
                         </button>
                    </div>

                     {/* File Upload with Multi-select and Merging UI */}
                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700">Documentos {isEditing && '(Opcional se já existir)'}</label>
                        <div className="mt-1 flex flex-col space-y-3">
                            <div className="flex items-center justify-center px-6 pt-5 pb-6 border-2 border-gray-300 border-dashed rounded-md bg-gray-50">
                                <div className="space-y-1 text-center">
                                    <UploadIcon className="mx-auto h-12 w-12 text-gray-400" />
                                    <div className="flex text-sm text-gray-600">
                                        <label htmlFor="file-upload" className="relative cursor-pointer bg-white rounded-md font-medium text-teal-600 hover:text-teal-500 focus-within:outline-none focus-within:ring-2 focus-within:ring-offset-2 focus-within:ring-teal-500 px-2 py-1 border border-teal-200 shadow-sm">
                                            <span>Selecionar arquivos (PDFs serão mesclados)</span>
                                            <input id="file-upload" name="file-upload" type="file" className="sr-only" multiple accept=".pdf,.doc,.docx" onChange={handleFileChange} />
                                        </label>
                                    </div>
                                    <p className="text-xs text-gray-500">Selecione vários PDFs para juntar em um só.</p>
                                </div>
                            </div>

                            {files.length > 0 && (
                                <div className="bg-white border rounded-md p-3 shadow-inner">
                                    <h5 className="text-xs font-bold text-gray-500 uppercase mb-2">Arquivos selecionados:</h5>
                                    <ul className="space-y-2">
                                        {files.map((f, i) => (
                                            <li key={i} className="flex justify-between items-center bg-gray-50 p-2 rounded border text-sm">
                                                <div className="flex items-center overflow-hidden">
                                                    <span className={`flex-shrink-0 w-8 text-center text-[10px] font-bold py-0.5 rounded mr-2 ${f.type === 'application/pdf' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'}`}>
                                                        {f.type === 'application/pdf' ? 'PDF' : 'DOC'}
                                                    </span>
                                                    <span className="truncate text-gray-700">{f.name}</span>
                                                </div>
                                                <button type="button" onClick={() => removeFile(i)} className="text-red-400 hover:text-red-600 ml-2">
                                                    <TrashIcon className="w-4 h-4"/>
                                                </button>
                                            </li>
                                        ))}
                                    </ul>
                                    {files.length > 1 && (
                                        <div className="mt-3 p-2 bg-teal-50 rounded border border-teal-100 text-xs text-teal-700 italic">
                                            Os {files.length} arquivos acima serão mesclados em um único PDF final ao salvar.
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>
                </div>
                 <div className="flex justify-end items-center pt-4 border-t space-x-2 mt-6">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300" disabled={isSubmitting || isMerging}>Cancelar</button>
                    <button type="submit" className="px-4 py-2 bg-teal-600 text-white rounded-md hover:bg-teal-700 disabled:bg-teal-300" disabled={isSubmitting || isMerging}>
                        {isSubmitting || isMerging ? (isMerging ? 'Mesclando PDFs...' : 'Salvando...') : (isEditing ? 'Salvar Alterações' : 'Salvar Instrumento')}
                    </button>
                </div>
            </form>
        </Modal>
    );
};

export default NewLegalInstrumentModal;

import React, { useState, useEffect, useRef } from 'react';
import { LegalInstrument, Partnership, LegalInstrumentType } from '../types';
import Modal from './Modal';
import { PlusIcon, TrashIcon, UploadIcon, SearchIcon, XIcon } from './Icons';

interface NewLegalInstrumentModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (instrument: Omit<LegalInstrument, 'id' | 'addendums'>, file: File | null) => Promise<void>;
    partnerships: Partnership[];
    isSubmitting: boolean;
    preSelectedPartnership?: Partnership | null;
    instrumentToEdit?: LegalInstrument | null;
}

const initialState = {
    signatories: [''],
    type: LegalInstrumentType.PartnershipAgreement,
    linkedPartnershipIds: [] as string[],
    object: '',
    signatureDate: new Date().toISOString().split('T')[0],
    expirationDate: '',
    document: undefined,
    observations: '',
};

const NewLegalInstrumentModal: React.FC<NewLegalInstrumentModalProps> = ({ isOpen, onClose, onSubmit, partnerships, isSubmitting, preSelectedPartnership, instrumentToEdit }) => {
    const [formState, setFormState] = useState<Omit<LegalInstrument, 'id' | 'addendums'>>(initialState);
    const [files, setFiles] = useState<File[]>([]);
    const [isMerging, setIsMerging] = useState(false);

    // Searchable dropdown states
    const [searchTerm, setSearchTerm] = useState('');
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const isEditing = !!instrumentToEdit;

    useEffect(() => {
        if (isOpen) {
            if (instrumentToEdit) {
                setFormState({
                    signatories: instrumentToEdit.signatories,
                    type: instrumentToEdit.type,
                    linkedPartnershipIds: instrumentToEdit.linkedPartnershipIds,
                    object: instrumentToEdit.object,
                    signatureDate: instrumentToEdit.signatureDate,
                    expirationDate: instrumentToEdit.expirationDate,
                    document: instrumentToEdit.document,
                    observations: instrumentToEdit.observations,
                });
            } else {
                setFormState({
                    ...initialState,
                    linkedPartnershipIds: preSelectedPartnership ? [preSelectedPartnership.id] : [],
                });
            }
            setFiles([]);
            setSearchTerm('');
            setIsDropdownOpen(false);
            setIsMerging(false);
        }
    }, [isOpen, preSelectedPartnership, instrumentToEdit]);

    // Handle click outside to close dropdown
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormState(prev => ({ ...prev, [name]: value }));
    };

    const togglePartnership = (partnershipId: string) => {
        setFormState(prev => {
            const isSelected = prev.linkedPartnershipIds.includes(partnershipId);
            const newIds = isSelected 
                ? prev.linkedPartnershipIds.filter(id => id !== partnershipId)
                : [...prev.linkedPartnershipIds, partnershipId];
            return { ...prev, linkedPartnershipIds: newIds };
        });
        setSearchTerm('');
        setIsDropdownOpen(false);
    };

    const handleSignatoryChange = (index: number, value: string) => {
        const newSignatories = [...formState.signatories];
        newSignatories[index] = value;
        setFormState(prev => ({ ...prev, signatories: newSignatories }));
    };

    const addSignatory = () => {
        setFormState(prev => ({ ...prev, signatories: [...prev.signatories, ''] }));
    };

    const removeSignatory = (index: number) => {
        setFormState(prev => ({ ...prev, signatories: prev.signatories.filter((_, i) => i !== index) }));
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            const selected = Array.from(e.target.files);
            setFiles(prev => [...prev, ...selected]);
        }
        // Limpa o valor do input para permitir selecionar o mesmo arquivo novamente se for deletado da lista
        if (fileInputRef.current) fileInputRef.current.value = '';
    };

    const removeFile = (index: number) => {
        setFiles(prev => prev.filter((_, i) => i !== index));
    };

    const mergePDFs = async (pdfFiles: File[]): Promise<File> => {
        const PDFLib = (window as any).PDFLib;
        if (!PDFLib) {
            throw new Error("A biblioteca de PDF (PDF-Lib) não foi carregada corretamente.");
        }

        const { PDFDocument } = PDFLib;
        const mergedPdf = await PDFDocument.create();

        for (const file of pdfFiles) {
            const arrayBuffer = await file.arrayBuffer();
            const pdf = await PDFDocument.load(arrayBuffer);
            const copiedPages = await mergedPdf.copyPages(pdf, pdf.getPageIndices());
            copiedPages.forEach((page: any) => mergedPdf.addPage(page));
        }

        const mergedPdfBytes = await mergedPdf.save();
        return new File([mergedPdfBytes], "instrumento_unificado.pdf", { type: 'application/pdf' });
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (formState.linkedPartnershipIds.length === 0) {
            alert("Por favor, selecione pelo menos uma parceria para vincular.");
            return;
        }

        let finalFile: File | null = null;

        try {
            if (files.length > 1) {
                setIsMerging(true);
                const onlyPdfs = files.filter(f => f.type === 'application/pdf');

                if (onlyPdfs.length < files.length) {
                    const proceed = window.confirm("Atenção: Apenas arquivos PDF podem ser mesclados. Outros formatos selecionados serão ignorados na junção. Deseja continuar?");
                    if (!proceed) {
                        setIsMerging(false);
                        return;
                    }
                }

                if (onlyPdfs.length === 0) {
                    alert("Não há arquivos PDF válidos para mesclar.");
                    setIsMerging(false);
                    return;
                }

                finalFile = await mergePDFs(onlyPdfs);
            } else if (files.length === 1) {
                finalFile = files[0];
            }

            await onSubmit(formState, finalFile);
        } catch (error: any) {
            console.error("Erro no processamento do formulário:", error);
            alert("Ocorreu um erro ao salvar: " + (error.message || "Erro desconhecido"));
        } finally {
            setIsMerging(false);
        }
    };

    // Filtering logic for the search
    const filteredPartnerships = partnerships.filter(p => {
        const matchesSearch = p.reference.toLowerCase().includes(searchTerm.toLowerCase()) || 
                             p.title.toLowerCase().includes(searchTerm.toLowerCase());
        const notSelected = !formState.linkedPartnershipIds.includes(p.id);
        return matchesSearch && notSelected;
    });

    const selectedPartnershipsData = partnerships.filter(p => formState.linkedPartnershipIds.includes(p.id));

    return (
        <Modal isOpen={isOpen} onClose={onClose} title={isEditing ? 'Editar Instrumento Jurídico' : 'Criar Novo Instrumento Jurídico'}>
            <form onSubmit={handleSubmit}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {/* Header Fields */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Tipo</label>
                        <select name="type" value={formState.type} onChange={handleChange} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm">
                            {Object.values(LegalInstrumentType).map(t => <option key={t} value={t}>{t}</option>)}
                        </select>
                    </div>

                    {/* Searchable Partnership Multi-select */}
                    <div className="md:row-span-2">
                        <label className="block text-sm font-medium text-gray-700 mb-1">Vincular Parcerias (Busca por texto)</label>
                        <div className="relative" ref={dropdownRef}>
                            <div className="relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                    <SearchIcon className="h-4 w-4 text-gray-400" />
                                </div>
                                <input
                                    type="text"
                                    placeholder="Digite a referência ou nome da parceria..."
                                    value={searchTerm}
                                    onChange={(e) => {
                                        setSearchTerm(e.target.value);
                                        setIsDropdownOpen(true);
                                    }}
                                    onFocus={() => setIsDropdownOpen(true)}
                                    className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm"
                                />
                            </div>

                            {isDropdownOpen && (
                                <ul className="absolute z-20 mt-1 w-full bg-white shadow-lg max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
                                    {filteredPartnerships.length === 0 ? (
                                        <li className="text-gray-500 cursor-default select-none relative py-2 px-3">
                                            {searchTerm ? 'Nenhuma parceria encontrada.' : 'Comece a digitar para buscar...'}
                                        </li>
                                    ) : (
                                        filteredPartnerships.map((p) => (
                                            <li
                                                key={p.id}
                                                className="cursor-pointer select-none relative py-2 pl-3 pr-9 hover:bg-teal-50 text-gray-900 border-b border-gray-50 last:border-0"
                                                onClick={() => togglePartnership(p.id)}
                                            >
                                                <div className="flex flex-col">
                                                    <span className="font-bold text-teal-700">{p.reference}</span>
                                                    <span className="text-xs text-gray-500 truncate">{p.title}</span>
                                                </div>
                                            </li>
                                        ))
                                    )}
                                </ul>
                            )}
                        </div>

                        {/* Selected Items Pills */}
                        <div className="mt-3 flex flex-wrap gap-2">
                            {selectedPartnershipsData.length > 0 ? (
                                selectedPartnershipsData.map(p => (
                                    <div key={p.id} className="inline-flex items-center bg-teal-50 text-teal-800 text-xs font-semibold px-2.5 py-1 rounded-full border border-teal-200">
                                        <span className="max-w-[150px] truncate">{p.reference}</span>
                                        <button 
                                            type="button" 
                                            onClick={() => togglePartnership(p.id)}
                                            className="ml-1.5 inline-flex items-center justify-center text-teal-400 hover:text-teal-600 focus:outline-none"
                                        >
                                            <XIcon className="h-3 w-3" />
                                        </button>
                                    </div>
                                ))
                            ) : (
                                <span className="text-xs text-red-500 italic">Nenhuma parceria selecionada.</span>
                            )}
                        </div>
                    </div>

                    <div className="md:col-span-1">
                         <label className="block text-sm font-medium text-gray-700">Data de Assinatura</label>
                        <input type="date" name="signatureDate" value={formState.signatureDate} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-700">Data de Vigência</label>
                        <input type="date" name="expirationDate" value={formState.expirationDate} onChange={handleChange} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" />
                    </div>

                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700">Objeto</label>
                        <textarea name="object" value={formState.object} onChange={handleChange} rows={3} required className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm"></textarea>
                    </div>

                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700">Observações</label>
                        <textarea name="observations" value={formState.observations} onChange={handleChange} rows={2} className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm"></textarea>
                    </div>

                    {/* Signatories */}
                    <div className="md:col-span-2">
                         <label className="block text-sm font-medium text-gray-700">Signatários</label>
                         {formState.signatories.map((s, index) => (
                             <div key={index} className="flex items-center space-x-2 mt-1">
                                 <input type="text" value={s} onChange={e => handleSignatoryChange(index, e.target.value)} required className="block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm" placeholder={`Signatário ${index + 1}`} />
                                 {formState.signatories.length > 1 && (
                                     <button type="button" onClick={() => removeSignatory(index)} className="text-red-500 hover:text-red-700 p-1">
                                        <TrashIcon className="w-5 h-5"/>
                                     </button>
                                 )}
                             </div>
                         ))}
                         <button type="button" onClick={addSignatory} className="text-sm text-teal-600 hover:text-teal-800 mt-2 flex items-center">
                            <PlusIcon className="w-4 h-4 mr-1"/>
                            Adicionar Signatário
                         </button>
                    </div>

                     {/* File Upload UI */}
                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                            Documentos do Instrumento {isEditing && '(Opcional se já existir)' }
                        </label>
                        <div className="space-y-3">
                            {/* Botão de Seleção Real */}
                            <div className="flex items-center justify-center w-full">
                                <label className="flex flex-col items-center justify-center w-full h-32 border-2 border-gray-300 border-dashed rounded-lg cursor-pointer bg-gray-50 hover:bg-gray-100 transition-colors">
                                    <div className="flex flex-col items-center justify-center pt-5 pb-6">
                                        <UploadIcon className="w-8 h-8 mb-4 text-gray-500" />
                                        <p className="mb-2 text-sm text-gray-500"><span className="font-semibold">Clique para selecionar</span> ou arraste arquivos</p>
                                        <p className="text-xs text-gray-500">PDFs serão mesclados automaticamente (DOC/DOCX aceitos individualmente)</p>
                                    </div>
                                    <input 
                                        type="file" 
                                        ref={fileInputRef}
                                        className="hidden" 
                                        multiple 
                                        accept=".pdf,.doc,.docx" 
                                        onChange={handleFileChange} 
                                    />
                                </label>
                            </div>

                            {/* Lista de Arquivos Selecionados */}
                            {files.length > 0 && (
                                <div className="mt-2 bg-white border border-gray-200 rounded-md p-3 shadow-sm">
                                    <h5 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-2">Arquivos na fila ({files.length}):</h5>
                                    <ul className="space-y-1">
                                        {files.map((file, idx) => (
                                            <li key={`${file.name}-${idx}`} className="flex justify-between items-center bg-gray-50 px-3 py-2 rounded text-sm border border-gray-100">
                                                <div className="flex items-center truncate">
                                                    <span className={`flex-shrink-0 w-8 text-center text-[10px] font-bold py-0.5 rounded mr-3 ${file.type === 'application/pdf' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'}`}>
                                                        {file.type === 'application/pdf' ? 'PDF' : 'DOC'}
                                                    </span>
                                                    <span className="truncate text-gray-600 font-medium">{file.name}</span>
                                                    <span className="ml-2 text-[10px] text-gray-400">({(file.size / 1024).toFixed(0)} KB)</span>
                                                </div>
                                                <button type="button" onClick={() => removeFile(idx)} className="text-gray-400 hover:text-red-500 transition-colors ml-2">
                                                    <TrashIcon className="w-4 h-4"/>
                                                </button>
                                            </li>
                                        ))}
                                    </ul>
                                    {files.length > 1 && (
                                        <div className="mt-3 p-2 bg-amber-50 rounded border border-amber-100 text-[11px] text-amber-700 flex items-start">
                                            <span className="mr-1">⚠️</span>
                                            <span><strong>Nota:</strong> {files.filter(f => f.type === 'application/pdf').length} arquivo(s) PDF serão mesclados em um único documento ao salvar.</span>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                <div className="flex justify-end items-center pt-4 border-t space-x-2 mt-6">
                    <button 
                        type="button" 
                        onClick={onClose} 
                        className="px-4 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300 transition-colors" 
                        disabled={isSubmitting || isMerging}
                    >
                        Cancelar
                    </button>
                    <button 
                        type="submit" 
                        className="px-6 py-2 bg-teal-600 text-white rounded-md hover:bg-teal-700 disabled:bg-teal-300 font-medium shadow-sm transition-all" 
                        disabled={isSubmitting || isMerging || (files.length === 0 && !isEditing)}
                    >
                        {isMerging ? (
                            <span className="flex items-center">
                                <svg className="animate-spin -ml-1 mr-3 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                                Mesclando...
                            </span>
                        ) : isSubmitting ? 'Salvando...' : (isEditing ? 'Salvar Alterações' : 'Salvar Instrumento')}
                    </button>
                </div>
            </form>
        </Modal>
    );
};

