                                                        {new Date(expiration + 'T00:00:00') < new Date() && <span className="ml-2 text-xs text-red-600 font-bold">(Vencido)</span>}
                                                    </td>
                                                    <td className="px-4 py-3 text-sm">
                                                        {inst.folderWebUrl ? (
                                                            <a href={inst.folderWebUrl} target="_blank" rel="noopener noreferrer" className="text-teal-600 hover:underline flex items-center">
                                                                <CollectionIcon className="w-4 h-4 mr-1"/> Abrir
                                                            </a>
                                                        ) : (
                                                            <span className="text-gray-400">N/A</span>
                                                        )}
                                                    </td>
                                                    <td className="px-4 py-3 text-sm text-right space-x-2">
                                                        <button onClick={() => onSelectLegalInstrument(inst)} className="text-teal-600 hover:text-teal-900 font-medium">Detalhes</button>
                                                        {isAdmin && !isConsultant && onDeleteLegalInstrument && (
                                                            <button onClick={() => onDeleteLegalInstrument(inst.id)} className="text-red-400 hover:text-red-600">
                                                                <TrashIcon className="w-4 h-4 inline" />
                                                            </button>
                                                        )}
                                                    </td>
                                                </tr>
                                            );
                                        })}
                                    </tbody>
                                </table>
                            </div>
                        ) : (
                            <p className="text-sm text-gray-500">Nenhum instrumento jurídico vinculado a esta parceria.</p>
                        )}
                    </DetailCard>

                    {/* History Section - Moved here to be main content */}
                    <DetailCard title="Histórico Completo">
                         <div className="space-y-4 max-h-[600px] overflow-y-auto pr-2">
                            {sortedHistory.map((entry, index) => (
                                <div key={entry.id || index} className="flex items-start space-x-3 pb-3 border-b border-gray-100 last:border-0">
                                    <div className="bg-teal-100 p-2 rounded-full mt-1 flex-shrink-0">
                                        <div className="w-2 h-2 bg-teal-600 rounded-full"></div>
                                    </div>
                                    <div className="flex-grow">
                                        <div className="flex justify-between items-start">
                                            <p className="text-xs text-gray-400 mb-1">{new Date(entry.date).toLocaleString()}</p>
                                            <span className="text-xs bg-gray-100 text-gray-600 px-2 py-0.5 rounded-full">{entry.user}</span>
                                        </div>
                                        {entry.link ? (
                                            <button onClick={() => handleHistoryLinkClick(entry.link!)} className="text-sm text-teal-600 hover:underline text-left hover:text-teal-800 transition-colors block">
                                                {entry.description}
                                            </button>
                                        ) : (
                                            <p className="text-sm text-gray-700 whitespace-pre-wrap">{entry.description}</p>
                                        )}
                                    </div>
                               </div>
                            ))}
                            {sortedHistory.length === 0 && <p className="text-sm text-gray-500">Nenhum histórico registrado.</p>}
                        </div>
                    </DetailCard>

                     {partnership.partners.length > 0 && (
                        <DetailCard title="Parceiros Envolvidos">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                {partnership.partners.map(partner => (
                                    <div key={partner.id} className="p-3 bg-gray-50 rounded-md border">
                                        <p className="font-semibold text-gray-800">{partner.name}</p>
                                        <p className="text-sm text-gray-600">Coordenador: {partner.coordinator}</p>
                                    </div>
                                ))}
                            </div>
                        </DetailCard>
                    )}
                </div>

                {/* Right Column (Docs, Tasks) */}
                <div className="lg:col-span-1 space-y-6">

                    {/* Documents */}
                     <DetailCard title="Documentos">
                        <div className="space-y-3 max-h-96 overflow-y-auto">
                            {partnership.documents.map((doc) => (
                                <div key={doc.id} id={`document-${doc.id}`} className="p-3 bg-gray-50 rounded-md border flex flex-col">
                                    <div className="flex justify-between items-start mb-1">
                                        <p className="text-sm font-medium text-gray-800 break-all">{doc.file.name}</p>
                                        {doc.webUrl && (
                                            <a href={doc.webUrl} target="_blank" rel="noopener noreferrer" className="text-teal-600 hover:text-teal-800 p-1" title="Acessar documento">
                                                <CollectionIcon className="w-4 h-4"/>
                                            </a>
                                        )}
                                    </div>
                                    <p className="text-xs text-gray-500 italic mb-1">{doc.observations}</p>
                                    <p className="text-xs text-gray-400 text-right">{new Date(doc.date).toLocaleDateString()}</p>
                                </div>
                            ))}
                            {partnership.documents.length === 0 && <p className="text-sm text-gray-500">Nenhum documento.</p>}
                        </div>
                        {!isConsultant && (
                            <div className="mt-6 pt-4 border-t">
                                <h4 className="text-sm font-semibold text-gray-800 mb-3">Adicionar Novo Documento</h4>
                                <form onSubmit={(e) => { e.preventDefault(); handleUploadDocument(); }} className="space-y-3">
                                    <div>
                                        <label htmlFor="fileDescription" className="block text-xs font-medium text-gray-700">Descrição</label>
                                        <textarea
                                            id="fileDescription"
                                            rows={2}
                                            value={fileDescription}
                                            onChange={(e) => setFileDescription(e.target.value)}
                                            className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-1 px-2 focus:outline-none focus:ring-teal-500 focus:border-teal-500 text-xs"
                                            placeholder="Descrição do documento..."
                                            required
                                        />
                                    </div>
                                    <div>
                                        <label htmlFor="file-upload" className="block text-xs font-medium text-gray-700">Arquivo</label>
                                        <div className="mt-1">
                                            <input
                                                type="file"
                                                id="file-upload"
                                                ref={fileInputRef}
                                                onChange={handleFileChange}
                                                required
                                                className="block w-full text-xs text-gray-500
                                                    file:mr-2 file:py-1 file:px-2
                                                    file:rounded-md file:border-0
                                                    file:text-xs file:font-semibold
                                                    file:bg-teal-50 file:text-teal-700
                                                    hover:file:bg-teal-100"
                                            />
                                        </div>
                                    </div>
                                    <div className="flex justify-end">
                                        <button
                                            type="submit"
                                            className="inline-flex justify-center py-1 px-3 border border-transparent shadow-sm text-xs font-medium rounded-md text-white bg-teal-600 hover:bg-teal-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-teal-500 disabled:bg-teal-400 disabled:cursor-not-allowed"
                                            disabled={isUploading || !fileToUpload || !fileDescription.trim()}
                                        >
                                            {isUploading ? 'Enviando...' : 'Salvar'}
                                        </button>
                                    </div>
                                </form>
                            </div>
                        )}
                    </DetailCard>

                    {/* Tasks */}
                    <DetailCard 
                        title="Tarefas Associadas"
                        action={!isConsultant ? (
                            <button 
                                onClick={onAddNewTask}
                                className="flex items-center text-xs bg-teal-600 text-white px-2 py-1 rounded hover:bg-teal-700"
                                title="Criar tarefa para esta parceria"
                            >
                                <PlusIcon className="w-3 h-3 mr-1"/> Nova
                            </button>
                        ) : undefined}
                    >
                        {tasks.length > 0 ? tasks.filter(task => !isConsultant || task.assignedTo.some(u => u.id === currentUser.id)).map(task => {
                            const dueDate = new Date(task.dueDate + 'T00:00:00');
                            const today = new Date();
                            today.setHours(0,0,0,0);
                            const isOverdue = !task.completed && dueDate < today;

                            return (
                                <div 
                                    key={task.id} 
                                    onClick={() => onTaskClick(task.id)}
                                    className={`p-3 rounded-md border-l-4 mb-2 flex justify-between items-start cursor-pointer hover:shadow-md transition-shadow ${task.completed ? 'border-green-500 bg-green-50 hover:bg-green-100' : isOverdue ? 'border-red-500 bg-red-50 hover:bg-red-100' : 'border-yellow-500 bg-yellow-50 hover:bg-yellow-100'}`}
                                    title="Clique para ver detalhes"
                                >
                                    <div>
                                        <div className="flex items-center">
                                             <p className="font-semibold text-gray-800 text-sm hover:underline hover:text-teal-800">{task.title}</p>
                                             <ArrowRightIcon className="w-3 h-3 ml-2 text-gray-400" />
                                        </div>
                                        <p className="text-xs text-gray-600 mt-1">Resp: {task.assignedTo.map(u => u.name).join(', ')}</p>
                                        <p className={`text-xs mt-1 ${isOverdue ? 'text-red-600 font-bold' : 'text-gray-500'}`}>Vencimento: {dueDate.toLocaleDateString()}</p>
                                    </div>
                                    {!isConsultant && onDeleteTask && (
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); onDeleteTask(task.id); }} 
                                            className="text-red-400 hover:text-red-600 p-1"
                                            title="Excluir Tarefa"
                                        >
                                            <TrashIcon className="w-4 h-4" />
                                        </button>
                                    )}
                                </div>
                            );
                        }) : <p className="text-sm text-gray-500">Nenhuma tarefa associada.</p>}
                    </DetailCard>

                </div>
            </div>

            <NewHistoryEntryModal
                isOpen={isHistoryModalOpen}
                onClose={() => setIsHistoryModalOpen(false)}
                onSubmit={handleHistorySubmit}
            />

        </div>
    );
};

export default PartnershipDetailView;

import React, { useState } from 'react';
import { LegalInstrument, Partnership, LegalInstrumentType, User } from '../types';
import { TrashIcon, SearchIcon, PencilIcon } from './Icons';

interface LegalInstrumentViewProps {
    legalInstruments: LegalInstrument[];
    partnerships: Partnership[];
    onNewInstrument: () => void;
    onSelectInstrument: (instrument: LegalInstrument) => void;
    onDeleteInstrument?: (instrumentId: number) => void;
    onEditInstrument: (instrument: LegalInstrument) => void;
    currentUser: User;
}

const getCurrentExpirationDate = (instrument: LegalInstrument): string => {
    if (instrument.addendums.length === 0) {
        return instrument.expirationDate;
    }
    const latestAddendum = instrument.addendums.reduce((latest, current) => {
        return new Date(current.newExpirationDate + 'T00:00:00') > new Date(latest.newExpirationDate + 'T00:00:00') ? current : latest;
    });
    return latestAddendum.newExpirationDate;
};


const LegalInstrumentView: React.FC<LegalInstrumentViewProps> = ({ legalInstruments, partnerships, onNewInstrument, onSelectInstrument, onDeleteInstrument, onEditInstrument, currentUser }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [typeFilter, setTypeFilter] = useState<string>('');
    const [statusFilter, setStatusFilter] = useState<string>(''); // 'active' | 'expired' | ''

    const isAdmin = currentUser.role === 'Administrador';
    const isConsultant = currentUser.role === 'Consulta';

    const getDaysUntilExpiration = (date: string) => {
        const diff = new Date(date + 'T00:00:00').getTime() - new Date().getTime();
        return Math.ceil(diff / (1000 * 3600 * 24));
    };

    const filteredInstruments = legalInstruments.filter(inst => {
        const matchesType = typeFilter ? inst.type === typeFilter : true;

        const currentExpiration = getCurrentExpirationDate(inst);
        const daysLeft = getDaysUntilExpiration(currentExpiration);
        const isExpired = daysLeft <= 0;

        let matchesStatus = true;
        if (statusFilter === 'active') {
            matchesStatus = !isExpired;
        } else if (statusFilter === 'expired') {
            matchesStatus = isExpired;
        }

        const searchLower = searchTerm.toLowerCase();
        const formattedId = String(inst.id).padStart(4, '0');
        const partnershipsStr = inst.linkedPartnershipIds
            .map(id => partnerships.find(p => p.id === id)?.reference || '')
            .join(' ');

        const matchesSearch = 
            formattedId.includes(searchLower) ||
            inst.type.toLowerCase().includes(searchLower) ||
            partnershipsStr.toLowerCase().includes(searchLower) ||
            inst.signatories.some(s => s.toLowerCase().includes(searchLower)) ||
            inst.object.toLowerCase().includes(searchLower);

        return matchesType && matchesSearch && matchesStatus;
    });

    return (
        <div className="w-full">
             <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                <h2 className="text-2xl font-semibold text-gray-700">Instrumentos Jurídicos</h2>

                <div className="flex flex-col md:flex-row gap-2 w-full md:w-auto items-center">
                    <div className="relative w-full md:w-64">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                            <SearchIcon className="h-5 w-5 text-gray-400" />
                        </div>
                        <input 
                            type="text" 
                            placeholder="Pesquisar (Nº, Parceiro, Signatário...)" 
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="pl-10 pr-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm w-full"
                        />
                    </div>

                    <select 
                        value={typeFilter} 
                        onChange={(e) => setTypeFilter(e.target.value)} 
                        className="py-2 px-3 border border-gray-300 rounded-md focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm w-full md:w-auto"
                    >
                        <option value="">Todos os Tipos</option>
                        {Object.values(LegalInstrumentType).map(t => (
                            <option key={t} value={t}>{t}</option>
                        ))}
                    </select>

                    <select 
                        value={statusFilter} 
                        onChange={(e) => setStatusFilter(e.target.value)} 
                        className="py-2 px-3 border border-gray-300 rounded-md focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm w-full md:w-auto"
                    >
                        <option value="">Todos os Status</option>
                        <option value="active">Vigentes</option>
                        <option value="expired">Vencidos</option>
                    </select>

                    {isAdmin && !isConsultant && (
                        <button onClick={onNewInstrument} className="px-4 py-2 bg-teal-600 text-white rounded-md hover:bg-teal-700 whitespace-nowrap w-full md:w-auto">
                            Novo Instrumento
                        </button>
                    )}
                </div>
            </div>

            <div className="bg-white shadow-md rounded-lg overflow-x-auto">
                 <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                        <tr>
                            <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Nº</th>
                            <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Tipo</th>
                            <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Vigência</th>
                            <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider w-64">Parcerias Vinculadas</th>
                            <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Signatários</th>
                            <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                            {!isConsultant && <th scope="col" className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Ações</th>}
                        </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                        {filteredInstruments.sort((a, b) => b.id - a.id).map(inst => {
                            const currentExpiration = getCurrentExpirationDate(inst);
                            const daysLeft = getDaysUntilExpiration(currentExpiration);
                            const formattedId = String(inst.id).padStart(4, '0');

                            const isCritical = daysLeft <= 60;

                            return (
                                <tr key={inst.id} className={`hover:bg-gray-100 cursor-pointer transition-colors ${isCritical ? 'bg-red-50' : ''}`} onClick={() => onSelectInstrument(inst)}>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{formattedId}</td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-700">{inst.type}</td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                        {new Date(currentExpiration + 'T00:00:00').toLocaleDateString()}
                                    </td>
                                    <td className="px-6 py-4 text-sm text-gray-500 whitespace-normal break-words max-w-xs">
                                        {inst.linkedPartnershipIds.length > 0 
                                            ? inst.linkedPartnershipIds.map(id => partnerships.find(p => p.id === id)?.reference).join(', ')
                                            : <span className="text-gray-400 italic">Sem vínculo</span>
                                        }
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 max-w-xs truncate" title={inst.signatories.join(', ')}>
                                        {inst.signatories.join(', ')}
                                    </td>
                                     <td className="px-6 py-4 whitespace-nowrap">
                                        {daysLeft <= 0 ? (
                                             <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-gray-200 text-gray-800">Vencido</span>
                                        ) : daysLeft <= 30 ? (
                                            <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-red-100 text-red-800">Vence em {daysLeft} dias</span>
                                        ) : daysLeft <= 60 ? (
                                            <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-yellow-100 text-yellow-800">Vence em {daysLeft} dias</span>
                                        ) : (
                                            <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-lime-100 text-lime-800">Vigente</span>
                                        )}
                                    </td>
                                    {!isConsultant && (
                                        <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium space-x-2">
                                            {isAdmin && (
                                                <>
                                                    <button 
                                                        onClick={(e) => { e.stopPropagation(); onEditInstrument(inst); }} 
                                                        className="text-teal-600 hover:text-teal-900 p-1"
                                                        title="Editar Instrumento"
                                                    >
                                                        <PencilIcon className="w-5 h-5"/>
                                                    </button>
                                                    {onDeleteInstrument && (
                                                        <button onClick={(e) => { e.stopPropagation(); onDeleteInstrument(inst.id); }} className="text-red-400 hover:text-red-600 p-1">
                                                            <TrashIcon className="w-5 h-5"/>
                                                        </button>
                                                    )}
                                                </>
                                            )}
                                        </td>
                                    )}
                                </tr>
                            );
                        })}
                        {filteredInstruments.length === 0 && (
                            <tr>
                                <td colSpan={isConsultant ? 6 : 7} className="px-6 py-4 text-center text-sm text-gray-500">
                                    Nenhum instrumento encontrado com os filtros atuais.
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default LegalInstrumentView;

import React, { useState, useEffect } from 'react';
import { LegalInstrument, LegalInstrumentAddendum, User, Partnership } from '../types';
import Modal from './Modal';
import { PlusIcon, TrashIcon, PencilIcon } from './Icons';

interface LegalInstrumentDetailModalProps {
    isOpen: boolean;
    onClose: () => void;
    instrument: LegalInstrument | null;
    partnerships: Partnership[];
    onAddAddendum: (instrumentId: number, addendumData: Omit<LegalInstrumentAddendum, 'id'>, file: File | null) => void;
    onUpdateAddendum?: (instrumentId: number, addendumId: string, updatedData: Partial<LegalInstrumentAddendum>, file: File | null) => void;
    onDeleteAddendum?: (instrumentId: number, addendumId: string) => void;
    currentUser: User | null;
}

const getCurrentExpirationDate = (instrument: LegalInstrument): string => {
    if (instrument.addendums.length === 0) {
        return instrument.expirationDate;
    }
    const latestAddendum = instrument.addendums.reduce((latest, current) => {
        return new Date(current.newExpirationDate + 'T00:00:00') > new Date(latest.newExpirationDate + 'T00:00:00') ? current : latest;
    });
    return latestAddendum.newExpirationDate;
};

const InfoRow: React.FC<{ label: string; children: React.ReactNode }> = ({ label, children }) => (
    <div className="grid grid-cols-3 gap-4 text-sm py-2 border-b border-gray-100">
        <dt className="font-medium text-gray-500">{label}</dt>
        <dd className="text-gray-800 col-span-2">{children}</dd>
    </div>
);


const LegalInstrumentDetailModal: React.FC<LegalInstrumentDetailModalProps> = ({ isOpen, onClose, instrument, partnerships, onAddAddendum, onUpdateAddendum, onDeleteAddendum, currentUser }) => {
    const initialState = {
        signatureDate: '',
        newExpirationDate: '',
    };
    const [formState, setFormState] = useState(initialState);
    const [showAddForm, setShowAddForm] = useState(false);
    const [editingAddendumId, setEditingAddendumId] = useState<string | null>(null);
    const [file, setFile] = useState<File | null>(null);

    const isAdmin = currentUser?.role === 'Administrador';
    const isConsultant = currentUser?.role === 'Consulta';

    useEffect(() => {
        if (!isOpen) {
            setShowAddForm(false);
            setEditingAddendumId(null);
            setFormState(initialState);
            setFile(null);
        }
    }, [isOpen]);

    if (!instrument) return null;

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        setFormState(prev => ({...prev, [name]: value}));
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            setFile(e.target.files[0]);
        } else {
            setFile(null);
        }
    };

    const handleStartEdit = (addendum: LegalInstrumentAddendum) => {
        setFormState({
            signatureDate: addendum.signatureDate,
            newExpirationDate: addendum.newExpirationDate,
        });
        setEditingAddendumId(addendum.id);
        setShowAddForm(true);
        setFile(null);
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (formState.signatureDate && formState.newExpirationDate) {
            if (editingAddendumId && onUpdateAddendum) {
                 onUpdateAddendum(instrument.id, editingAddendumId, formState, file);
            } else {
                 onAddAddendum(instrument.id, formState, file);
            }
            setFormState(initialState);
            setShowAddForm(false);
            setEditingAddendumId(null);
            setFile(null);
        }
    };

    const sortedAddendums = [...instrument.addendums].sort((a,b) => new Date(b.signatureDate + 'T00:00:00').getTime() - new Date(a.signatureDate + 'T00:00:00').getTime());
    const currentExpirationDate = getCurrentExpirationDate(instrument);

    const linkedPartnershipRefs = instrument.linkedPartnershipIds
        .map(id => {
            const p = partnerships.find(partner => partner.id === id);
            return p ? p.reference : 'Ref Removida';
        })
        .join('; ');

    return (
        <Modal
            isOpen={isOpen}
            onClose={onClose}
            title={`Detalhes do Instrumento Jurídico #${String(instrument.id).padStart(4, '0')}`}
        >
            <div className="space-y-6">
                <div>
                    <h4 className="text-md font-semibold text-gray-700 mb-2">Informações Gerais</h4>
                    <dl>
                        <InfoRow label="Tipo">{instrument.type}</InfoRow>
                        <InfoRow label="Objeto">{instrument.object}</InfoRow>
                        <InfoRow label="Refs. Parcerias">{linkedPartnershipRefs || 'Nenhuma'}</InfoRow>
                        <InfoRow label="Signatários">{instrument.signatories.join(', ')}</InfoRow>
                        <InfoRow label="Data de Assinatura">{new Date(instrument.signatureDate + 'T00:00:00').toLocaleDateString()}</InfoRow>
                        <InfoRow label="Vigência Original">{new Date(instrument.expirationDate + 'T00:00:00').toLocaleDateString()}</InfoRow>
                        <InfoRow label="Vigência Atual">{new Date(currentExpirationDate + 'T00:00:00').toLocaleDateString()}</InfoRow>
                        <InfoRow label="Pasta no SharePoint">
                            {instrument.folderWebUrl ? (
                                <a href={instrument.folderWebUrl} target="_blank" rel="noopener noreferrer" className="text-indigo-600 hover:underline">
                                    Acessar pasta
