                                    <tr key={project.id}>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 font-medium">{project.name}</td>
                                        <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
