            setMicrosoftAuthState(response ? 'signedIn' : 'signedOut');
        } catch (error: any) {
            if (error.errorCode === 'user_cancelled') {
                console.log("User cancelled the sign-in process.");
            } else {
                console.error("Interactive sign-in failed:", error);
