        try {
            const parsed = parseUsers(fileContent);
            const existingEmails = new Set(users.map(u => u.email.toLowerCase()));
            const newUsers = parsed.filter(u => !existingEmails.has(u.email.toLowerCase())).map(u => ({ ...u, id: `user-${uuidv4()}` }));
            setUsers(prev => [...prev, ...newUsers]);
            alert(`${newUsers.length} de ${parsed.length} novos usuários foram importados com sucesso!`);
        } catch (error: any) {
            alert(`Erro ao importar usuários: ${error.message}`);
        }
    };

    const toCSV = (data: any[], headers: string[], separator = ';') => {
        const headerRow = headers.join(separator);
        const rows = data.map(row => headers.map(fieldName => {
            let val = row[fieldName] || '';
            if (val === undefined || val === null) val = '';
            // Basic handling of arrays/objects for CSV view
            if (typeof val === 'object') val = JSON.stringify(val);
            // Escape quotes and wrap in quotes
            const stringVal = String(val).replace(/"/g, '""'); 
            return `"${stringVal}"`; 
        }).join(separator));
        return [headerRow, ...rows].join('\n');
    };

    const handleCloudBackup = async () => {
        if (!isMicrosoftSignedIn || !msalInstance) {
             alert('É necessário estar conectado à Microsoft para realizar o backup na nuvem.');
             return;
        }

        setIsBackingUp(true);
        const dateStr = new Date().toISOString().split('T')[0];

        try {
             // 1. Partnerships CSV
             const partnershipHeaders = ['reference', 'title', 'status', 'projectType', 'funder', 'folderWebUrl', 'entryDate', 'approvedValue'];
             // Flatten/Enhance data for export
             const flatPartnerships = partnerships.map(p => ({
                 ...p,
                 folderWebUrl: p.folderWebUrl || ''
             }));
             const partnershipsCSV = toCSV(flatPartnerships, partnershipHeaders);

             // 2. Legal Instruments CSV
             const instrumentHeaders = ['id', 'type', 'object', 'signatureDate', 'expirationDate', 'folderWebUrl'];
             const flatInstruments = legalInstruments.map(i => ({
                 ...i,
                 folderWebUrl: i.folderWebUrl || ''
             }));
             const instrumentsCSV = toCSV(flatInstruments, instrumentHeaders);

             // 3. Users CSV
             const userHeaders = ['name', 'email', 'role'];
             const usersCSV = toCSV(users, userHeaders);

             // 4. Tasks CSV
             const taskHeaders = ['title', 'description', 'dueDate', 'completed'];
             const tasksCSV = toCSV(tasks, taskHeaders);

             await MicrosoftApi.uploadBackupFiles(msalInstance, [
                 { name: `backup_parcerias_${dateStr}.csv`, content: partnershipsCSV },
                 { name: `backup_instrumentos_${dateStr}.csv`, content: instrumentsCSV },
                 { name: `backup_usuarios_${dateStr}.csv`, content: usersCSV },
                 { name: `backup_tarefas_${dateStr}.csv`, content: tasksCSV },
             ]);

             alert('Backup CSV realizado com sucesso na pasta do sistema no SharePoint!');
        } catch (error) {
             console.error("Backup failed:", error);
             alert("Falha ao realizar o backup. Verifique o console.");
        } finally {
            setIsBackingUp(false);
        }
    };

    const handleToggleNotifications = () => {
        setIsNotificationsOpen(prev => !prev);
        if (!isNotificationsOpen) setNotifications(prev => prev.map(n => ({...n, read: true})));
    };

    const handleNotificationLinkClick = (link: Notification['link']) => {
        if (!link) return;
        const partnership = partnerships.find(p => p.id === link.partnershipId);
        if (partnership) {
            setSelectedPartnership(partnership);
            setActiveView(View.Partnerships);
            if (link.instrumentId) {
                setSelectedLegalInstrument(legalInstruments.find(i => i.id === link.instrumentId) || null);
            }
        }
        setIsNotificationsOpen(false);
    };

    // Handler for navigation from task view (clicking Partnership reference)
    const handleNavigateToPartnership = (partnership: Partnership) => {
        setSelectedPartnership(partnership);
        setActiveView(View.Partnerships);
    };

    const renderContent = () => {
        if (selectedPartnership) {
            return <PartnershipDetailView
                partnership={selectedPartnership}
                legalInstruments={legalInstruments.filter(li => li.linkedPartnershipIds.includes(selectedPartnership.id))}
                tasks={tasks.filter(t => t.partnershipId === selectedPartnership.id)}
                users={users}
                currentUser={currentUser!}
                onBack={() => setSelectedPartnership(null)}
                addHistoryEntry={addHistoryEntry}
                onAddDocument={addDocumentToPartnership}
                onSelectLegalInstrument={setSelectedLegalInstrument}
                onStatusChange={handlePartnershipStatusChange}
                isMicrosoftSignedIn={isMicrosoftSignedIn}
                onEdit={handleOpenPartnershipModal}
                onDelete={handleDeletePartnership}
                onDeleteTask={handleDeleteTask}
                onDeleteLegalInstrument={handleDeleteLegalInstrument}
                onAddNewInstrument={() => {
                    setPreSelectedPartnershipForInstrument(selectedPartnership);
                    setEditingLegalInstrument(null);
                    setIsNewLegalInstrumentModalOpen(true);
                }}
                onAddNewTask={() => {
                    handleOpenTaskModal(null, selectedPartnership.id);
                }}
                onTaskClick={handlePartnershipDetailTaskClick}
                internalProjects={internalProjects}
            />;
        }

        switch (activeView) {
            case View.Dashboard: 
                return <Dashboard 
                            partnerships={partnerships} 
                            legalInstruments={legalInstruments} 
                            tasks={tasks} 
                            setActiveView={setActiveView} 
                            currentUser={currentUser!}
                            readHistoryIds={readHistoryIds}
                            onMarkHistoryRead={handleMarkHistoryRead}
                            onTaskClick={handleDashboardTaskClick}
                        />;
            case View.Partnerships: return <PartnershipView partnerships={partnerships} onSelectPartnership={setSelectedPartnership} onNewPartnership={() => handleOpenPartnershipModal(null)} currentUser={currentUser!} />;
            case View.LegalInstruments: 
                return <LegalInstrumentView 
                    legalInstruments={legalInstruments} 
                    partnerships={partnerships} 
                    onNewInstrument={() => { setEditingLegalInstrument(null); setIsNewLegalInstrumentModalOpen(true); }} 
                    onSelectInstrument={setSelectedLegalInstrument} 
                    onDeleteInstrument={handleDeleteLegalInstrument}
                    onEditInstrument={handleOpenInstrumentModal}
                    currentUser={currentUser!}
                />;
            case View.Tasks: 
                return <TaskView 
                    tasks={tasks} 
                    partnerships={partnerships} 
                    users={users} 
                    onNewTask={() => handleOpenTaskModal(null)} 
                    onCompleteTask={handleCompleteTask} 
                    onDeleteTask={handleDeleteTask}
                    onEditTask={handleOpenTaskModal}
                    highlightedTaskId={highlightedTaskId}
                    onSelectPartnership={handleNavigateToPartnership}
                    currentUser={currentUser!}
                />;
            case View.Settings: return <SettingsView currentUser={currentUser!} users={users} onNewUser={() => handleOpenUserModal(null)} onEditUser={handleOpenUserModal} onDeleteUser={handleDeleteUser} onImportPartnerships={handleImportPartnerships} onImportLegalInstruments={handleImportLegalInstruments} onImportUsers={handleImportUsers} systemSettings={systemSettings} onUpdateSettings={handleUpdateSettings} onCloudBackup={handleCloudBackup} isBackingUp={isBackingUp} internalProjects={internalProjects} onSaveInternalProject={handleSaveInternalProject} onUpdateInternalProject={handleUpdateInternalProject} onDeleteInternalProject={handleDeleteInternalProject} />;
            default: 
                return <Dashboard 
                            partnerships={partnerships} 
                            legalInstruments={legalInstruments} 
                            tasks={tasks} 
                            setActiveView={setActiveView} 
                            currentUser={currentUser!}
                            readHistoryIds={readHistoryIds}
                            onMarkHistoryRead={handleMarkHistoryRead}
                            onTaskClick={handleDashboardTaskClick}
                        />;
        }
    };

    const MicrosoftLoginView = ({ onSignIn }: { onSignIn: () => void }) => (
        <div className="flex items-center justify-center min-h-screen bg-gray-100 relative">
            <div className="w-full max-w-md p-8 space-y-6 bg-white rounded-lg shadow-md z-10">
                <div className="text-center">
                    <CTVLogoIcon className="w-48 h-auto mx-auto mb-6" />
                    <h2 className="mt-4 text-2xl font-bold text-gray-900">
                        Gestor de Parcerias
                    </h2>
                    <p className="mt-2 text-sm text-gray-600">
                        Faça login com sua conta Microsoft para acessar o sistema.
                    </p>
                </div>
                <button
                    onClick={onSignIn}
                    className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-teal-600 hover:bg-teal-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-teal-500"
                >
                    Entrar com a Microsoft
                </button>
            </div>
            <div className="absolute bottom-2 text-gray-300 text-xs text-center w-full z-0">
                Desenvolvido por Priscila Passos
            </div>
        </div>
    );

    if (microsoftAuthState === 'pending') {
        return (
            <div className="flex items-center justify-center h-screen bg-gray-100">
                <p className="text-lg text-gray-600">Conectando à nuvem...</p>
            </div>
        );
    }

    if (!isMicrosoftSignedIn) {
        return <MicrosoftLoginView onSignIn={handleInteractiveSignIn} />;
    }

    if (!currentUser) {
        return (
            <div className="flex items-center justify-center h-screen bg-gray-100">
                <p className="text-lg text-gray-600">Verificando usuário...</p>
            </div>
        );
    }

    return (
        <div className="flex h-screen bg-gray-50">
            <Sidebar 
                activeView={activeView} 
                setActiveView={(view) => { setActiveView(view); setSelectedPartnership(null); }} 
                onNewPartnership={() => handleOpenPartnershipModal(null)} 
                currentUser={currentUser} 
                isCollapsed={!isSidebarOpen}
            />
            <div className="flex flex-col flex-1 w-full">
                <Header 
                    currentUser={currentUser} 
                    onLogout={handleLogout} 
                    notifications={notifications} 
                    onToggleNotifications={handleToggleNotifications} 
                    microsoftAuthState={microsoftAuthState} 
                    onInteractiveSignIn={handleInteractiveSignIn} 
                    syncStatus={syncStatus} 
                    lastSyncTime={lastSyncTime}
                    onToggleSidebar={handleToggleSidebar}
                    onOpenHelp={() => setIsHelpModalOpen(true)}
                />
                <main className="h-full overflow-y-auto relative flex flex-col">
                    <div className="w-full px-6 mx-auto my-6 flex-grow overflow-x-hidden">
                        {renderContent()}
                    </div>
                    {/* Footer Credit */}
                    <div className="py-2 text-center mt-auto">
                         <span className="text-gray-300 text-xs">Desenvolvido por Priscila Passos</span>
                    </div>

                     <NotificationsPanel isOpen={isNotificationsOpen} notifications={notifications} onClose={() => setIsNotificationsOpen(false)} onLinkClick={handleNotificationLinkClick} />
                </main>
            </div>
            <NewPartnershipModal isOpen={isPartnershipModalOpen} onClose={() => { setIsPartnershipModalOpen(false); setEditingPartnership(null); }} onSubmit={handlePartnershipSubmit} users={users} isSubmitting={isSubmitting} isMicrosoftSignedIn={isMicrosoftSignedIn} partnershipToEdit={editingPartnership} internalProjects={internalProjects} />

            <NewLegalInstrumentModal 
                isOpen={isNewLegalInstrumentModalOpen} 
                onClose={() => { setIsNewLegalInstrumentModalOpen(false); setEditingLegalInstrument(null); setPreSelectedPartnershipForInstrument(null); }} 
                onSubmit={handleSaveLegalInstrument} 
                partnerships={partnerships} 
                isSubmitting={isSubmitting} 
                preSelectedPartnership={preSelectedPartnershipForInstrument}
                instrumentToEdit={editingLegalInstrument}
            />

            <LegalInstrumentDetailModal 
                isOpen={!!selectedLegalInstrument} 
                onClose={() => setSelectedLegalInstrument(null)} 
                instrument={selectedLegalInstrument} 
                partnerships={partnerships}
                onAddAddendum={handleAddAddendum} 
                onUpdateAddendum={handleUpdateAddendum}
                onDeleteAddendum={handleDeleteAddendum}
                currentUser={currentUser}
            />

            <NewTaskModal 
                isOpen={isNewTaskModalOpen} 
                onClose={() => { setIsNewTaskModalOpen(false); setEditingTask(null); setPreSelectedPartnershipForTask(null); }} 
                onSubmit={handleSaveTask} 
                partnerships={partnerships} 
                users={users} 
                taskToEdit={editingTask}
                preSelectedPartnership={preSelectedPartnershipForTask}
            />

            <UserManagementModal isOpen={isUserModalOpen} onClose={() => { setIsUserModalOpen(false); setEditingUser(null); }} onSubmit={handleSaveUser} userToEdit={editingUser} />
            <HelpModal isOpen={isHelpModalOpen} onClose={() => setIsHelpModalOpen(false)} />
        </div>
    );
};

export default App;

import React, { useRef, useState } from 'react';
import { User, SystemSettings, InternalProject } from '../types';
import { PlusIcon, PencilIcon, TrashIcon, DownloadIcon, UploadIcon, TableIcon, RefreshIcon, CollectionIcon, CheckCircleIcon, XIcon } from './Icons';

interface SettingsViewProps {
    currentUser: User;
    users: User[];
    onNewUser: () => void;
    onEditUser: (user: User) => void;
    onDeleteUser: (userId: string) => void;
    onImportPartnerships: (fileContent: string) => void;
    onImportLegalInstruments: (fileContent: string) => void;
    onImportUsers: (fileContent: string) => void;
    systemSettings: SystemSettings;
    onUpdateSettings: (settings: SystemSettings) => void;
    onCloudBackup: () => void;
    isBackingUp: boolean;
    internalProjects: InternalProject[];
    onSaveInternalProject: (name: string) => void;
    onUpdateInternalProject: (id: string, newName: string) => void;
    onDeleteInternalProject: (projectId: string) => void;
}

const SettingsView: React.FC<SettingsViewProps> = ({ 
    currentUser,
    users, 
    onNewUser, 
    onEditUser, 
    onDeleteUser,
    onImportPartnerships,
    onImportLegalInstruments,
    onImportUsers,
    systemSettings,
    onUpdateSettings,
    onCloudBackup,
    isBackingUp,
    internalProjects,
    onSaveInternalProject,
    onUpdateInternalProject,
    onDeleteInternalProject
}) => {
    const partnershipFileRef = useRef<HTMLInputElement>(null);
    const instrumentFileRef = useRef<HTMLInputElement>(null);
    const userFileRef = useRef<HTMLInputElement>(null);

    const [senderEmail, setSenderEmail] = useState(systemSettings.senderEmail);
    const [newInternalProjectName, setNewInternalProjectName] = useState('');

    // States for inline editing of internal projects
    const [editingProjectId, setEditingProjectId] = useState<string | null>(null);
    const [editingProjectName, setEditingProjectName] = useState('');

    const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>, handler: (content: string) => void) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (event) => {
                const content = event.target?.result as string;
                handler(content);
            };
            reader.readAsText(file);
        }
        e.target.value = ''; // Reset input
    };

    const handleSaveSettings = (e: React.FormEvent) => {
        e.preventDefault();
        onUpdateSettings({
            ...systemSettings,
            senderEmail: senderEmail.trim()
        });
    };

    const handleAddInternalProject = (e: React.FormEvent) => {
        e.preventDefault();
        if (newInternalProjectName.trim()) {
            onSaveInternalProject(newInternalProjectName);
            setNewInternalProjectName('');
        }
    };

    const startEditingProject = (project: InternalProject) => {
        setEditingProjectId(project.id);
        setEditingProjectName(project.name);
    };

    const cancelEditingProject = () => {
        setEditingProjectId(null);
        setEditingProjectName('');
    };

    const saveEditedProject = () => {
        if (editingProjectId && editingProjectName.trim()) {
            onUpdateInternalProject(editingProjectId, editingProjectName);
            setEditingProjectId(null);
            setEditingProjectName('');
        }
    };

    const generateCsvTemplate = (type: 'partnerships' | 'instruments' | 'users') => {
        let headers: string[] = [];
        if (type === 'partnerships') {
            headers = ['reference', 'title', 'status', 'projectType', 'funder', 'funderCoordinator', 'ctvCoordinatorEmail', 'ctvResearcherEmail', 'ctvBusinessPartnerEmail', 'entryDate', 'executionStartDate', 'approvedValue', 'projectNumber', 'observations'];
        } else if (type === 'instruments') {
            headers = ['id', 'type', 'object', 'signatureDate', 'expirationDate', 'linkedPartnershipReferences', 'signatories', 'observations'];
        } else {
            headers = ['name', 'email', 'role', 'platform'];
        }
        // Using semicolon for Brazilian Excel compatibility
        const csvContent = headers.join(';');
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.setAttribute('download', `template_${type}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    if (currentUser.role !== 'Administrador') {
        return (
            <div className="container mx-auto text-center py-10">
                <h2 className="text-2xl font-semibold text-gray-700">Acesso Negado</h2>
                <p className="text-gray-500 mt-2">Você não tem permissão para acessar esta página.</p>
            </div>
        );
    }


    return (
        <div className="w-full space-y-8">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-semibold text-gray-700">Configurações</h2>
                <button 
                    onClick={onCloudBackup} 
                    disabled={isBackingUp}
                    className="flex items-center px-4 py-2 bg-teal-700 text-white rounded-md hover:bg-teal-800 disabled:bg-teal-400 shadow-sm"
                >
                     {isBackingUp ? (
                        <>
                           <RefreshIcon className="w-4 h-4 mr-2 animate-spin" />
                           Salvando Backup...
                        </>
                     ) : (
                        <>
                           <CollectionIcon className="w-4 h-4 mr-2" />
                           Fazer Backup CSV na Nuvem
                        </>
                     )}
                </button>
            </div>

             {/* System Configuration */}
             <div className="bg-white p-6 rounded-lg shadow-md">
                <h3 className="text-lg font-semibold text-gray-800 border-b pb-2 mb-4">Configurações do Sistema</h3>
                <form onSubmit={handleSaveSettings} className="max-w-2xl">
                    <div className="mb-4">
                        <label htmlFor="senderEmail" className="block text-sm font-medium text-gray-700">
                            E-mail do Remetente de Notificações
                        </label>
                        <p className="text-xs text-gray-500 mt-1 mb-2">
                            Este e-mail será usado para enviar notificações automáticas (ex: novas tarefas, parcerias).
                            Para que funcione, os usuários do sistema devem ter permissão de "Enviar Como" (Send As) neste e-mail configurada no Microsoft 365.
                            Deixe em branco para usar o e-mail do usuário logado.
                        </p>
                        <div className="flex gap-2">
                            <input
                                type="email"
                                id="senderEmail"
                                value={senderEmail}
                                onChange={(e) => setSenderEmail(e.target.value)}
                                placeholder="ex: cadastro@ctvacinas.org"
                                className="flex-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm"
                            />
                            <button
                                type="submit"
                                className="px-4 py-2 bg-teal-600 text-white rounded-md hover:bg-teal-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-teal-500"
                            >
                                Salvar
                            </button>
                        </div>
                    </div>
                </form>
            </div>

            {/* Internal Projects Registry */}
            <div className="bg-white p-6 rounded-lg shadow-md">
                <h3 className="text-lg font-semibold text-gray-800 border-b pb-2 mb-4">Cadastro de Projetos Internos / Editais</h3>
                <form onSubmit={handleAddInternalProject} className="mb-6">
                    <div className="flex gap-2 items-end max-w-lg">
                        <div className="flex-1">
                            <label htmlFor="internalProjectName" className="block text-sm font-medium text-gray-700 mb-1">
                                Nome do Projeto ou Edital
                            </label>
                            <input
                                type="text"
                                id="internalProjectName"
                                value={newInternalProjectName}
                                onChange={(e) => setNewInternalProjectName(e.target.value)}
                                placeholder="Digite o nome..."
                                className="block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-teal-500 focus:border-teal-500 sm:text-sm"
                            />
                        </div>
                        <button
                            type="submit"
                            className="flex items-center px-4 py-2 bg-teal-600 text-white rounded-md hover:bg-teal-700 transition-colors h-[38px]"
                        >
                            <PlusIcon className="w-4 h-4 mr-2" />
                            Adicionar
                        </button>
                    </div>
                </form>

                <div className="overflow-x-auto max-h-60 overflow-y-auto border rounded-md">
                    <table className="min-w-full divide-y divide-gray-200">
                        <thead className="bg-gray-50 sticky top-0">
                            <tr>
                                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Nome</th>
                                <th scope="col" className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider w-32">Ações</th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                            {internalProjects && internalProjects.length > 0 ? (
                                internalProjects.map(project => (
                                    <tr key={project.id}>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 font-medium">
                                            {editingProjectId === project.id ? (
                                                <input
                                                    type="text"
                                                    value={editingProjectName}
                                                    onChange={(e) => setEditingProjectName(e.target.value)}
                                                    className="block w-full border border-teal-500 rounded-md shadow-sm py-1 px-2 focus:outline-none focus:ring-teal-500 sm:text-sm"
                                                    autoFocus
                                                />
                                            ) : (
                                                project.name
                                            )}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                                            {editingProjectId === project.id ? (
                                                <div className="flex justify-end space-x-2">
                                                    <button 
                                                        onClick={saveEditedProject} 
                                                        className="text-green-600 hover:text-green-900 p-1"
                                                        title="Salvar"
                                                    >
                                                        <CheckCircleIcon className="w-5 h-5"/>
                                                    </button>
                                                    <button 
                                                        onClick={cancelEditingProject} 
                                                        className="text-gray-500 hover:text-gray-700 p-1"
                                                        title="Cancelar"
                                                    >
                                                        <XIcon className="w-5 h-5"/>
                                                    </button>
                                                </div>
                                            ) : (
                                                <div className="flex justify-end space-x-2">
                                                    <button 
                                                        onClick={() => startEditingProject(project)} 
                                                        className="text-teal-600 hover:text-teal-900 p-1"
                                                        title="Editar Nome"
                                                    >
                                                        <PencilIcon className="w-5 h-5"/>
                                                    </button>
                                                    <button 
                                                        onClick={() => onDeleteInternalProject(project.id)} 
                                                        className="text-red-600 hover:text-red-900 p-1"
                                                        title="Excluir"
                                                    >
                                                        <TrashIcon className="w-5 h-5"/>
                                                    </button>
                                                </div>
                                            )}
                                        </td>
                                    </tr>
                                ))
                            ) : (
                                <tr>
                                    <td colSpan={2} className="px-6 py-8 text-center text-sm text-gray-500">Nenhum registro cadastrado.</td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Import Data */}
            <div className="bg-white p-6 rounded-lg shadow-md">
                <h3 className="text-lg font-semibold text-gray-800 border-b pb-2 mb-4">Importar Dados</h3>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {/* Partnerships Import */}
                    <div className="p-4 border rounded-md">
                        <h4 className="font-medium text-gray-700">Parcerias</h4>
                        <p className="text-sm text-gray-500 mt-1 mb-3">Importe múltiplas parcerias de um arquivo CSV.</p>
                        <div className="flex space-x-2">
                             <button onClick={() => generateCsvTemplate('partnerships')} className="flex items-center text-sm px-3 py-2 bg-gray-100 text-gray-700 rounded-md hover:bg-gray-200">
                                <DownloadIcon className="w-4 h-4 mr-2" />
                                Template
                            </button>
                            <button onClick={() => partnershipFileRef.current?.click()} className="flex items-center text-sm px-3 py-2 bg-teal-500 text-white rounded-md hover:bg-teal-600">
                                <UploadIcon className="w-4 h-4 mr-2" />
                                Importar
                            </button>
                            <input type="file" ref={partnershipFileRef} className="hidden" accept=".csv" onChange={(e) => handleFileImport(e, onImportPartnerships)} />
                        </div>
                    </div>

                    {/* Legal Instruments Import */}
                     <div className="p-4 border rounded-md">
                        <h4 className="font-medium text-gray-700">Instrumentos Jurídicos</h4>
                        <p className="text-sm text-gray-500 mt-1 mb-3">Importe múltiplos instrumentos de um arquivo CSV.</p>
